#!/usr/bin/env node
/* FERRAMENTAS DO MAESTRO — tudo num ficheiro.
 *
 * O arquivo comprimido era apagado pelo antivírus (falso positivo). Este
 * ficheiro é JavaScript simples: corre-o com o Node na raiz do repositório e
 * ele escreve a pasta `ferramentas/` inteira, com os 24 ficheiros.
 *
 *   node ferramentas-maestro.js
 *
 * Depois, para correr os testes:
 *
 *   node ferramentas/testar-tudo.js maestro.user.js
 */
const fs = require('fs');
const path = require('path');

const FICHEIROS = {
 "LEIA-ME.md": "# Testes do Maestro\n\nCada teste tira do `maestro.user.js` o código **real** — uma função, um módulo\ninteiro, um troço do núcleo — e corre-o contra um jogo simulado\n(`simulador.js`). Se o código mudar, o teste corre o código novo.\n\n## Correr\n\nPrecisa de Node 18 ou mais recente. Na raiz do repositório:\n\n```\nnode ferramentas/testar-tudo.js maestro.user.js\n```\n\nUm só: `node ferramentas/teste-encaixe.js maestro.user.js`\n\n**Regra:** uma versão só se entrega com tudo a passar. Uma mudança de\ncomportamento traz o teste que a prova — e, se possível, a prova de que o teste\nfalha sem ela (estragar o código de propósito e ver a falha).\n\n## O que cada um verifica\n\n| Ficheiro | O que tem de ser |\n|---|---|\n| `teste-nucleo.js` | O leitor da visão geral: cópia de 20 s, `fresca`, esquecer depois de um envio, pedidos ao mesmo tempo, 429, erros, sem Administrador. `ok: false` nunca é lista vazia. |\n| `teste-leitores.js` | Feitiços, Deuses e Reforço: a lista certa; o Reforço não traz tropa às cegas; o farm não ataca sem saber o favor a caminho; os três fazem um pedido só. |\n| `teste-alertas-esquiva.js` | Um ataque inimigo que só a visão geral traz é avisado e esquivado; voltas, revoltas, apoios de outros e comandos meus não; o mesmo ataque pelas duas fontes conta uma vez; leitura falhada não é desmentido. |\n| `teste-encaixe.js` | A leitura é sempre fresca (tem de ver o comando que acabou de sair); a razão de uma falha fica registada. |\n| `teste-colonizadores-revoltas.js` | Apoio (revoltas), Fundação e Expansão: sem saber que colonizadores vão a caminho, não sai nenhum. |\n| `teste-apoio-transportes.js` | O Apoio só junta transportes quando o alvo está noutra ilha; na mesma ilha a tropa vai a pé. |\n| `teste-fechar-ilha.js` | Cada conta escreve só a sua chave (enviei, falhei, desisti, lugar); quem lê o plano junta tudo; o dono ganha nas atribuições. |\n| `teste-relatorios.js` | Lê um relatório: tropa e perdas de cada lado, espionagem, quem ataca quem; guarda a maior força já vista por jogador. |\n| `teste-painel-relatorios.js` | O botão Guardar do painel não rebenta por faltar um campo, e guarda o que lá está. |\n| `teste-cancelamento.js` | Um `command_deleted: false` não passa por cancelado (Encaixe, Esquiva, Apoio); sem o campo, fica como estava. |\n| `teste-apoio-painel.js` | O botão \"actualizar\" pede os nomes em lote (um pedido, não um por alvo); o total por alvo soma as contas vivas. |\n| `teste-aldeias-vazias.js` | Aldeias prontas que não rendem nada em duas passagens seguidas: suspende, avisa e mostra o captcha. |\n| `teste-fechar-ilha-mapa.js` | A ilha lê-se na grelha de 20; cidades acima do lugar 20 contam; leitura falhada não é ilha vazia. |\n| `teste-fechar-ilha-vagas.js` | As vagas e o lugar vêm do jogo (`forceUpdate`), não do mapa; duas contas não pedem o mesmo lugar. |\n| `teste-vigia-mudo.js` | Correr não é fazer: o núcleo marca a hora de cada linha de ecrã e o vigia avisa quando um módulo vigiado passa horas sem produzir nada. |\n| `teste-encaixe-carga.js` | As composições enchem os transportes contando a pesquisa de porões (16 e 32), não a capacidade base. |\n| `teste-sentinelas.js` | Uma leitura da Ágora que não cobre todas as minhas cidades não prova que a aliada esteja a descoberto: não se manda outra sentinela. |\n| `teste-reforco-blocos.js` | Os modelos `Units` não chegam para dar a tropa por perdida: confirma-se na Ágora da origem antes de apagar o registo. |\n| `teste-esquiva-margem.js` | A margem de saída inclui o tempo que a preparação leva; sobe depressa, desce devagar, travada nos 3 min. |\n| `teste-fundacao-mapa.js` | A procura de ilhas pede seis blocos por pedido, com pausa, e pára quando o servidor começa a recusar. |\n| `teste-captcha.js` | Com um captcha no ecrã o ciclo pára **e** o núcleo avisa no Discord (logo, e de meia em meia hora). |\n\n## Formatos confirmados em jogo (espia, 11/09)\n\n- A lista da visão geral vem em `json.data.commands` (lê-se também `json.commands`).\n- Todas as cidades dão a mesma visão geral.\n- Comandos de outros jogadores: `started_at: 0`, `own_command: false`.\n- As minhas voltas: `return: true`, com origem e destino trocados.\n- Revoltas: `started_at` = fim da R1.\n- Colonizadores: `id` em texto (`colonization_5120`), `island_x`, `island_y`, `number_on_island`.\n- Modelos e visão geral partilham o número do comando.\n- Acções: `send_units`, `cancelCommand` (com `command_deleted`), `cast`, `buildUp`, `trade` e o `frontend_bridge` confirmam com `success`/`error`; o `build` do recrutamento não devolve nem um nem outro.\n- Vagas de uma ilha: `forceUpdate` da colonização → `island_info.uninhabited_place_count` e um `target_number_on_island` livre, diferente a cada pedido. O jogo aceita fundar em qualquer lugar livre. As ilhas têm 20 lugares.\n- Mapa: a grelha do `get_chunks` é de 20 (com 10 vem outro pedaço, sem cidades). Numa ilha há cidades acima do lugar 20 (vistas no 23) e entradas com `nr` nulo, que são aldeias.\n- Relatórios: o HTML vem em `plain.html` (topo da resposta, fora de `json`); tropas em `data-unit_id`/`data-unit_count`; lado em `report_side_attacker_unit`/`report_side_defender_unit`; espionagem em blocos ` spy `; perdas em `report_losts`; assunto em `<span class=\"subject\">`; cidade e jogador em base64 nos links.\n\n## Acrescentar um teste\n\nUm ficheiro `teste-<coisa>.js` nesta pasta (o `testar-tudo.js` apanha-o\nsozinho). O `simulador.js` dá o jogo (`jogo`), o núcleo (`carregarNucleo`), um\nmódulo a correr (`correr`), as respostas (`lista`, `ERRO`, `LIMITADO`) e o\ncontador (`verificador`).\n",
 "simulador.js": "/* O JOGO SIMULADO, partilhado pelos testes.\n *\n * Os testes não reescrevem o Maestro: tiram do `maestro.user.js` o código REAL\n * (uma função, um módulo inteiro, um troço do núcleo) e correm-no contra um\n * jogo de mentira — os modelos, as colecções e as respostas do servidor que\n * cada cenário precisa. Se o código mudar, o teste corre o código novo.\n *\n * Os formatos das respostas são os que a espia viu em jogo (11/09): a lista\n * da visão geral vem em `json.data.commands`; os comandos de outros vêm com\n * `started_at: 0`; os colonizadores têm `id` em texto (\"colonization_…\"). */\nconst fs = require('fs');\nconst vm = require('vm');\n\nconst AGORA_S = 2_000_000;   // hora do jogo, em segundos\n\nfunction ler(caminho) { return fs.readFileSync(caminho, 'utf8'); }\n\n/* Um troço de texto do ficheiro: de `inicio` até ao primeiro `fim` a seguir. */\nfunction tira(src, inicio, fim, depoisDe) {\n  const de = depoisDe ? src.indexOf(depoisDe) : 0;\n  const a = src.indexOf(inicio, de < 0 ? 0 : de);\n  if (a < 0) throw new Error('não encontrei no ficheiro: ' + inicio.slice(0, 60));\n  const b = src.indexOf(fim, a);\n  if (b < 0) throw new Error('não encontrei o fim de: ' + inicio.slice(0, 60));\n  return src.slice(a, b + fim.length);\n}\n\n/* Uma função de indentação 2, até ao `  }` que a fecha. */\nconst funcao = (src, inicio, depoisDe) => tira(src, inicio, '\\n  }\\n', depoisDe);\n\n/* Uma fábrica de módulo (coluna 0), até ao `}` que a fecha. */\nconst fabrica = (src, nome) => tira(src, `function ${nome}(opts) {`, '\\n}\\n');\n\n/* O leitor comum das respostas e o leitor da visão geral, do núcleo. */\nfunction blocoNucleo(src) {\n  const a = src.indexOf('  async function lerRespostaComum(resposta) {');\n  const b = src.indexOf('  /* ============ AVISO DE VERIFICAÇÃO DE BOT', a);\n  if (a < 0 || b < 0) throw new Error('não encontrei o leitor da visão geral no núcleo');\n  return src.slice(a, b);   // sem o comentário seguinte, que ficaria por fechar\n}\n\n/* O jogo. `op`:\n *   respostas  fila de respostas à visão geral ({ corpo, status }); a última repete\n *   movimentos modelos MovementsUnits · attack colecção Attack · units modelos Units\n *   semAdm     sem Administrador no modelo das assinaturas */\nfunction jogo(op) {\n  op = op || {};\n  const pedidos = [];\n  const fila = (op.respostas || []).slice();\n  const win = {\n    location: { origin: 'https://pt125.grepolis.com' },\n    Game: { csrfToken: 'TOK', townId: 111, player_id: 1, player_name: 'Shad0wRA', world_id: 'pt125',\n      constants: { units: { runtime_setup_time: 300 } } },\n    Timestamp: { now: () => AGORA_S, serverTime: () => AGORA_S },\n    ITowns: {\n      towns: { 111: {}, 222: {} },\n      getTown: (id) => ({\n        id: Number(id), getName: () => 'Cidade ' + id, name: 'Cidade ' + id,\n        units: () => ({ sword: 10 }), unitsOuter: () => ({}), unitsSupport: () => ({}),\n        getIslandCoordinateX: () => 100, getIslandCoordinateY: () => (Number(id) === 111 ? 100 : 110),\n        getBuildings: () => ({ getBuildingLevel: () => 0 }), researches: () => ({ attributes: {} }),\n        god: () => null, getGod: () => null,\n      }),\n      getCurrentTown: () => ({ id: 111 }),\n    },\n    GameData: { units: { sword: { speed: 8, is_naval: false, population: 1 }, archer: {}, hoplite: {}, bireme: {} } },\n    MM: {\n      getModels: () => ({\n        PremiumFeatures: op.semAdm ? { k: { attributes: {} } } : { k: { attributes: { curator: 9e12 } } },\n        MovementsUnits: op.movimentos || {},\n        Units: op.units || {},\n      }),\n      getCollections: () => ({\n        Attack: [{ models: (op.attack || []).map((a) => ({ attributes: a })) }],\n        TownGroup: [{ models: [] }], TownGroupTown: [{ models: [] }],\n      }),\n    },\n    gpAjax: { ajaxGet: (a, b, c, d, cb) => { if (cb) cb(); } },\n    console: { log: () => {} },\n    fetch: async (url) => {\n      pedidos.push(String(url));\n      let r;\n      if (/command_overview/.test(url)) {\n        r = fila.length > 1 ? fila.shift() : (fila[0] || { corpo: { json: { data: { commands: [] } } } });\n      } else if (/send_back/.test(url)) {\n        r = { corpo: { json: { success: 'A tropa vai a caminho.', all_units: {} } } };\n      } else {\n        r = { corpo: { json: {} } };\n      }\n      const texto = typeof r.corpo === 'string' ? r.corpo : JSON.stringify(r.corpo);\n      return { status: r.status || 200, text: async () => texto, json: async () => JSON.parse(texto) };\n    },\n    __maestroTravar: () => {},\n  };\n  win.__maestroTemAdministrador = () => {\n    try { return Number(Object.values(win.MM.getModels().PremiumFeatures)[0].attributes.curator) > AGORA_S; }\n    catch (e) { return false; }\n  };\n  const loja = {};\n  const localStorage = {\n    getItem: (k) => (k in loja ? loja[k] : null),\n    setItem: (k, v) => { loja[k] = String(v); },\n    removeItem: (k) => { delete loja[k]; },\n  };\n  const pedidosVG = () => pedidos.filter((u) => /command_overview/.test(u)).length;\n  return { win, pedidos, pedidosVG, loja, localStorage };\n}\n\n/* Tirar o Administrador a um jogo já montado. */\nfunction semAdministrador(j) {\n  const g = j.win.MM.getModels;\n  j.win.MM.getModels = () => Object.assign(g(), { PremiumFeatures: { k: { attributes: {} } } });\n}\n\n/* O núcleo do ficheiro na janela do jogo: `__maestroVisaoGeral` e companhia. */\nfunction carregarNucleo(src, j) {\n  const ctx = {\n    uw: j.win,\n    temAdministrador: () => j.win.__maestroTemAdministrador(), servidorTravado: () => false,\n    avisarCaptcha: async () => {}, guardarNaCaixa: () => {}, seErroDeCodigo: () => {}, log: () => {},\n  };\n  vm.createContext(ctx);\n  vm.runInContext(blocoNucleo(src), ctx);\n}\n\n/* Um módulo inteiro, pronto a correr. */\nfunction modulo(src, nome, j) {\n  const erros = [];\n  const ctx = {\n    /* `uw` é o do núcleo, no mesmo âmbito que os módulos no ficheiro verdadeiro. */\n    uw: j.win, window: j.win, localStorage: j.localStorage, console: { log: () => {}, warn: () => {} },\n    document: { createElement: () => ({ style: {} }), querySelector: () => null },\n    seErroDeCodigo: (e, onde) => erros.push(`${onde}: ${e && e.message}`),\n    limiteColonizador: () => 12.5, pareceColonizadorNC: () => false,\n    registarPorque: () => {}, fbLer: async () => null, fbApagar: async () => {},\n    /* Esperas curtas correm já; agendamentos longos (planos da esquiva) não. */\n    setTimeout: (f, ms) => { if ((Number(ms) || 0) <= 5000) Promise.resolve().then(f); return 0; },\n    clearTimeout: () => {},\n  };\n  vm.createContext(ctx);\n  const mod = vm.runInContext(fabrica(src, nome) + `\\n${nome}({ intervaloMin: 1 })`, ctx);\n  return { mod, erros };\n}\n\nfunction contexto(j, reg) {\n  return {\n    uw: j.win, WORLD: 'pt125',\n    log: (m) => reg.ecra.push(String(m)), logRotina: (m) => reg.rotina.push(String(m)),\n    sleep: async () => {}, rand: () => 0,\n    getMyTowns: () => [{ id: 111, name: 'Cidade 111' }, { id: 222, name: 'Cidade 222' }],\n    avisarDiscord: async (canal, aviso) => { reg.discord.push({ canal, aviso }); },\n    switchToTown: async () => {}, voltarEm: () => {}, ligado: () => true,\n  };\n}\n\n/* Montar o jogo, carregar o núcleo e correr um módulo `passagens` vezes. */\nasync function correr(src, nome, op, passagens, antes) {\n  const j = jogo(op);\n  carregarNucleo(src, j);\n  if (antes) antes(j);\n  const { mod, erros } = modulo(src, nome, j);\n  const reg = { ecra: [], rotina: [], discord: [] };\n  const c = contexto(j, reg);\n  for (let i = 0; i < (passagens || 1); i++) await mod.run(c);\n  return { reg, erros, vg: j.pedidosVG(), j };\n}\n\nconst ligar = (chave) => (j) => j.localStorage.setItem(chave, JSON.stringify({ ativo: true }));\n\n/* Respostas da visão geral. */\nconst lista = (cmds, extra) => ({ corpo: { json: Object.assign({ data: { commands: cmds } }, extra || {}) } });\nconst ERRO = { corpo: { json: { error: 'Ocorreu um erro.' } } };\nconst LIMITADO = { status: 429, corpo: '' };\n\nconst igual = (a, b) => JSON.stringify(a) === JSON.stringify(b);\n\n/* Contador de verificações de um ficheiro de teste. */\nfunction verificador(titulo) {\n  let n = 0, falhas = 0;\n  if (titulo) console.log(`\\n${titulo}`);\n  return {\n    secao: (t) => console.log(`\\n${t}`),\n    verifica(nome, cond, extra) {\n      n++;\n      if (cond) console.log('  ok  ', nome);\n      else {\n        falhas++;\n        console.log('  FALHA', nome, extra !== undefined ? JSON.stringify(extra, null, 1).slice(0, 1500) : '');\n      }\n    },\n    fim() {\n      console.log(`\\n${n - falhas}/${n} verificações passaram.`);\n      process.exit(falhas ? 1 : 0);\n    },\n  };\n}\n\nfunction ficheiroDoMaestro() {\n  const c = process.argv[2] || 'maestro.user.js';\n  if (!fs.existsSync(c)) {\n    console.error(`Não encontrei ${c}. Uso: node ${process.argv[1]} caminho/para/maestro.user.js`);\n    process.exit(2);\n  }\n  return ler(c);\n}\n\nmodule.exports = {\n  AGORA_S, ler, tira, funcao, fabrica, blocoNucleo, jogo, semAdministrador, carregarNucleo, modulo,\n  contexto, correr, ligar, lista, ERRO, LIMITADO, igual, verificador, ficheiroDoMaestro, vm,\n};\n",
 "testar-tudo.js": "/* CORRE TODOS OS TESTES contra um maestro.user.js.\n *\n *   node ferramentas/testar-tudo.js maestro.user.js\n *\n * Sai com erro se algum falhar — é o que se corre antes de entregar uma versão. */\nconst { spawnSync } = require('child_process');\nconst path = require('path');\nconst fs = require('fs');\n\nconst ficheiro = process.argv[2] || 'maestro.user.js';\nif (!fs.existsSync(ficheiro)) { console.error(`Não encontrei ${ficheiro}.`); process.exit(2); }\n\nconst aqui = __dirname;\nconst testes = fs.readdirSync(aqui).filter((f) => /^teste-.*\\.js$/.test(f)).sort();\nlet mal = 0;\nconst resumo = [];\nfor (const f of testes) {\n  const r = spawnSync(process.execPath, [path.join(aqui, f), ficheiro], { encoding: 'utf8', timeout: 300000 });\n  const saida = (r.stdout || '') + (r.stderr || '');\n  const linha = (saida.match(/(\\d+)\\/(\\d+) verificações passaram\\./) || [])[0] || 'REBENTOU';\n  const ok = r.status === 0;\n  if (!ok) { mal++; console.log(saida); }\n  resumo.push(`${ok ? 'ok   ' : 'FALHA'} ${f.padEnd(34)} ${linha}`);\n}\nconsole.log('\\n' + resumo.join('\\n'));\nconsole.log(mal ? `\\n${mal} ficheiro(s) com falhas.` : '\\nTudo a passar.');\nprocess.exit(mal ? 1 : 0);\n",
 "teste-aldeias-vazias.js": "/* ALDEIAS — recolher muito e não render nada: pergunta-se ao jogo.\n *\n * Visto em jogo (12/09, conta sem Capitão): \"Recolhidas 126 aldeia(s)\n * (~0 recursos)\" durante mais de uma hora. Por pedido directo o servidor\n * aceita e não dá nada, sem recusa nenhuma. Então abre-se uma aldeia e\n * carrega-se em Recolher: se houver verificação, o jogo mostra-a. Só aí se\n * suspende. O código REAL da recolha, com os modelos simulados.\n *\n *   node ferramentas/teste-aldeias-vazias.js maestro.user.js\n */\nconst S = require('./simulador');\nconst { vm, funcao, tira } = S;\nconst SRC = S.ficheiroDoMaestro();\nconst t = S.verificador('ALDEIAS — RECOLHA VAZIA');\nconst AL = 'function makeAldeiasModule(opts)';\n\n/* `rende` de cada aldeia pronta; `apareceu` = o captcha aparece ao clicar. */\nfunction montar(rende, apareceu) {\n  const chamadas = { tratou: [], mostrou: 0, individual: 0 };\n  const ctx = {\n    mUw: { Game: { player_name: 'MultiX' } }, mWorld: 'pt126', seErroDeCodigo: () => {}, console,\n    relacoesProntas: () => Array.from({ length: 126 }, (_, i) => ({ relationId: i, farmTownId: 900 + i, rende })),\n    temCapitao: () => false,\n    recolhaIndividual: async () => { chamadas.individual++; },\n    recolherEmMassa: async () => ({ ok: true }),\n    tratarCaptcha: async (c, onde) => { chamadas.tratou.push(onde); },\n    mostrarCaptchaPelaRecolha: async () => { chamadas.mostrou++; return !!apareceu; },\n    aldeiaParaMostrarCaptcha: () => ({ farmTownId: 900, townId: 111 }),\n  };\n  vm.createContext(ctx);\n  const txt = funcao(SRC, '  async function fazerRecolha(ctx, towns) {', AL) + '\\nfazerRecolha';\n  const f = vm.runInContext(txt, ctx);\n  const reg = { ecra: [], rotina: [] };\n  const c = { log: (m) => reg.ecra.push(String(m)), logRotina: (m) => reg.rotina.push(String(m)),\n    sleep: async () => {}, rand: () => 0 };\n  return { reg, chamadas, correr: () => f(c, [{ id: 111 }]) };\n}\n\n(async () => {\n  {\n    const m = montar(1800, false);\n    await m.correr();\n    t.verifica('aldeias que rendem: recolhe como sempre, sem abrir nada',\n      m.chamadas.individual === 1 && m.chamadas.mostrou === 0, m.chamadas);\n  }\n  {\n    const m = montar(0, true);\n    await m.correr();\n    t.verifica('a zero: abre a aldeia e carrega em Recolher', m.chamadas.mostrou === 1, m.chamadas);\n    t.verifica('... o captcha aparece: suspende e avisa', m.chamadas.tratou.length === 1\n      && /render zero/.test(m.chamadas.tratou[0]), m.chamadas);\n    t.verifica('... e não faz a recolha nessa passagem', m.chamadas.individual === 0, m.chamadas);\n  }\n  {\n    const m = montar(0, false);\n    await m.correr();\n    t.verifica('a zero mas sem captcha: NÃO suspende', !m.chamadas.tratou.length, m.chamadas);\n    t.verifica('... e a recolha segue na mesma', m.chamadas.individual === 1, m.chamadas);\n    t.verifica('... com a razão na rotina', m.reg.rotina.some((x) => /nenhuma rende nada/.test(x)), m.reg.rotina);\n  }\n  /* A SUSPENSÃO: enquanto houver verificação, e não meia hora fixa. */\n  {\n    const suspensao = (haCaptcha, hMin) => {\n      const loja = { 'grepoAldeias_captcha_v1': String(Date.now() - hMin * 60000) };\n      const ctx = {\n        armazem: { getItem: (k) => loja[k] || null, setItem: (k, v2) => { loja[k] = v2; },\n          removeItem: (k) => { delete loja[k]; } },\n        agoraServidorMs: () => Date.now(),\n        window: { __maestroHaCaptcha: () => haCaptcha },\n        CAPTCHA_KEY: 'grepoAldeias_captcha_v1',\n        seErroDeCodigo: () => {},\n      };\n      vm.createContext(ctx);\n      const f = vm.runInContext(funcao(SRC, '  function captchaAtivo() {', AL) + '\\ncaptchaAtivo', ctx);\n      return { activo: f(), marca: () => loja['grepoAldeias_captcha_v1'] };\n    };\n    const a = suspensao(true, 2);\n    t.verifica('captcha ainda no ecrã: continua suspenso', a.activo === true);\n    const b = suspensao(false, 2);\n    t.verifica('resolvido ao fim de 2 min: retoma já', b.activo === false, b.activo);\n    t.verifica('... e apaga a marca', !b.marca(), b.marca());\n    const c2 = suspensao(true, 45);\n    t.verifica('tecto de 30 min: não fica suspenso para sempre', c2.activo === false);\n  }\n  t.fim();\n})().catch((e) => { console.error('O TESTE REBENTOU:', e); process.exit(2); });\n",
 "teste-alertas-esquiva.js": "/* ALERTAS E ESQUIVA — a visão geral pelo núcleo, e o que dela se aproveita.\n *\n * O que tem de ser: um ataque inimigo que só a visão geral traz (started_at 0,\n * espia 11/09) é avisado e esquivado; voltas minhas, revoltas, apoios de outros\n * e comandos meus não; o mesmo ataque pelas duas fontes conta uma vez; uma\n * leitura falhada diz-se e não conta como desmentido; um pedido só para os dois.\n *\n *   node ferramentas/teste-alertas-esquiva.js maestro.user.js\n */\nconst S = require('./simulador');\nconst { AGORA_S, vm, tira, funcao, jogo, carregarNucleo, semAdministrador, correr, ligar, lista, ERRO, LIMITADO,\n  igual } = S;\nconst SRC = S.ficheiroDoMaestro();\n\nconst t = S.verificador('ALERTAS E ESQUIVA');\n\nconst INIMIGO = { id: 701, type: 'attack', own_command: false, return: false, cmd_return: false, started_at: 0,\n  origin_town_id: 9101, origin_town_name: 'Inimiga', origin_town_player_id: 77, origin_town_player_name: 'Vilão',\n  destination_town_id: 111, arrival_at: AGORA_S + 5400 };\nconst OUTROS = [\n  { id: 702, type: 'attack_land', own_command: true, return: true, cmd_return: true, started_at: AGORA_S - 1000,\n    origin_town_id: 9102, origin_town_player_id: 88, destination_town_id: 111, arrival_at: AGORA_S + 600 },\n  { id: 703, type: 'revolt', own_command: true, started_at: AGORA_S + 3600, origin_town_id: 9103,\n    destination_town_id: 222, arrival_at: AGORA_S + 7200 },\n  { id: 704, type: 'support', own_command: false, started_at: 0, origin_town_id: 9104,\n    destination_town_id: 111, arrival_at: AGORA_S + 400 },\n  { id: 705, type: 'attack_takeover', own_command: true, origin_town_id: 111, destination_town_id: 9999, arrival_at: AGORA_S + 800 },\n  { id: 706, type: 'attack_sea', own_command: true, started_at: AGORA_S - 50, origin_town_id: 222,\n    destination_town_id: 9998, arrival_at: AGORA_S + 900 },\n];\nconst MODELO = (id) => ({ mX: { attributes: { id, type: 'attack', target_town_id: 111, home_town_id: 9101,\n  town_name_origin: 'Inimiga', arrival_at: AGORA_S + 5400 } } });\nconst MODELO_222 = { m1: { attributes: { id: 601, type: 'attack', target_town_id: 222, home_town_id: 9005,\n  town_name_origin: 'DoModelo', arrival_at: AGORA_S + 7000 } } };\nconst naAttack = (tid) => ({ attack: [{ town_id: tid, incoming: 1 }] });\nconst op = (cmds, mais) => Object.assign({ respostas: [lista(cmds)] }, naAttack(111), mais || {});\nconst ligaA = ligar('grepoAlertas_cfg_v1');\nconst ligaE = ligar('grepoEsquiva_cfg_v1');\nconst nada = (r) => r.reg.rotina.some((x) => /nenhum ataque a chegar/.test(x));\nconst desmentidas = (r) => JSON.parse(r.j.localStorage.getItem('grepoEsquiva_desmentidas_v1') || '{}');\n\n(async () => {\n  t.secao('ALERTAS');\n  {\n    const r = await correr(SRC, 'makeAlertasModule', Object.assign({ respostas: [lista(OUTROS)], movimentos: MODELO_222 },\n      naAttack(222)), 1, ligaA);\n    t.verifica('ataque que os modelos trazem: um aviso', r.reg.discord.length === 1, r.reg);\n  }\n  {\n    const r = await correr(SRC, 'makeAlertasModule', op([INIMIGO].concat(OUTROS)), 1, ligaA);\n    t.verifica('ataque inimigo só na visão geral (started_at 0): um aviso, com o nome do atacante',\n      r.reg.discord.length === 1 && /Vilão/.test(JSON.stringify(r.reg.discord)), r.reg.discord);\n    t.verifica('... sem erros de código', r.erros.length === 0, r.erros);\n  }\n  {\n    const r = await correr(SRC, 'makeAlertasModule', op(OUTROS), 1, ligaA);\n    t.verifica('voltas minhas, revoltas, apoio de outro, conquista e ataque meus: nenhum aviso', r.reg.discord.length === 0, r.reg.discord);\n  }\n  for (const [nome, id] of [['com o mesmo número', 701], ['com outro número', 99701]]) {\n    const r = await correr(SRC, 'makeAlertasModule', op([INIMIGO].concat(OUTROS), { movimentos: MODELO(id) }), 1, ligaA);\n    t.verifica(`o mesmo ataque nos modelos e na visão geral, ${nome}: um aviso só`, r.reg.discord.length === 1, r.reg.discord);\n  }\n  {\n    const j = jogo(op([INIMIGO].concat(OUTROS), { movimentos: MODELO(99701) })); carregarNucleo(SRC, j); ligaA(j);\n    const m = S.modulo(SRC, 'makeAlertasModule', j).mod;\n    const reg = { ecra: [], rotina: [], discord: [] }; const c = S.contexto(j, reg);\n    await m.run(c);\n    j.win.MM.getModels = () => ({ PremiumFeatures: { k: { attributes: { curator: 9e12 } } }, MovementsUnits: {} });\n    j.win.__maestroVisaoGeralEsquecer();\n    await m.run(c);\n    t.verifica('passagem seguinte, o mesmo ataque pelo outro número: não repete o aviso', reg.discord.length === 1, reg.discord.length);\n  }\n  {\n    const r = await correr(SRC, 'makeAlertasModule', { respostas: [ERRO] }, 2, ligaA);\n    t.verifica('leitura falhada: diz no ecrã, com a razão', r.reg.ecra.length === 1\n      && /não consegui ler a visão geral \\(Ocorreu um erro\\.\\)/.test(r.reg.ecra[0]), r.reg);\n    t.verifica('... a segunda vez vai para a rotina, e um pedido por passagem', r.reg.rotina.some((m) => /não consegui ler/.test(m))\n      && r.vg === 2, { rotina: r.reg.rotina, vg: r.vg });\n  }\n  {\n    const r = await correr(SRC, 'makeAlertasModule', { respostas: [LIMITADO] }, 1, ligaA);\n    t.verifica('429: diz que o servidor limitou', /429/.test(r.reg.ecra[0] || ''), r.reg.ecra);\n  }\n\n  t.secao('ESQUIVA');\n  {\n    const r = await correr(SRC, 'makeEsquivaModule', op([INIMIGO].concat(OUTROS)), 1, ligaE);\n    t.verifica('ataque inimigo só na visão geral: vê-o (não diz \"nenhum ataque a chegar\")', !nada(r), r.reg);\n    t.verifica('... sem erros de código', r.erros.length === 0, r.erros);\n  }\n  {\n    const r = await correr(SRC, 'makeEsquivaModule', op(OUTROS), 1, ligaE);\n    t.verifica('voltas, revoltas, apoios e comandos meus: nenhum ataque', nada(r), r.reg);\n  }\n  {\n    const so = await correr(SRC, 'makeEsquivaModule', op(OUTROS, { movimentos: MODELO(701) }), 1, ligaE);\n    for (const [nome, id] of [['com o mesmo número', 701], ['com outro número', 99701]]) {\n      const r = await correr(SRC, 'makeEsquivaModule', op([INIMIGO].concat(OUTROS), { movimentos: MODELO(id) }), 1, ligaE);\n      t.verifica(`o mesmo ataque nas duas fontes, ${nome}: faz o mesmo que só com o modelo`,\n        igual(so.reg.ecra, r.reg.ecra) && igual(so.reg.rotina, r.reg.rotina), { so: so.reg, r: r.reg });\n    }\n  }\n  {\n    const r = await correr(SRC, 'makeEsquivaModule', op([OUTROS[4]]), 1, ligaE);\n    t.verifica('servidor responde e não confirma: conta um desmentido, e diz porquê',\n      (desmentidas(r)['111'] || {}).falhas === 1\n      && r.reg.rotina.some((m) => /devolveu 1 comando\\(s\\) mas nenhum para esta cidade/.test(m)), { d: desmentidas(r), rotina: r.reg.rotina });\n  }\n  {\n    const r = await correr(SRC, 'makeEsquivaModule', Object.assign({ respostas: [ERRO] }, naAttack(111)), 10, ligaE);\n    t.verifica('10 leituras falhadas: nenhum desmentido, nenhuma quarentena', !desmentidas(r)['111']\n      && !r.reg.rotina.some((m) => /deixo de perguntar/.test(m)), desmentidas(r));\n    t.verifica('... diz porquê na rotina', r.reg.rotina.some((m) =>\n      /não consegui ler a visão geral \\(Ocorreu um erro\\.\\).*não conta como desmentido/.test(m)), r.reg.rotina);\n    t.verifica('... no ecrã uma vez só, sem dizer \"nenhum ataque a chegar\"',\n      r.reg.ecra.filter((m) => /não consegui ler/.test(m)).length === 1 && !nada(r), r.reg);\n  }\n  {\n    const r = await correr(SRC, 'makeEsquivaModule', Object.assign({ respostas: [LIMITADO] }, naAttack(111)), 1, ligaE);\n    t.verifica('429: diz que o servidor está a limitar', /429/.test(r.reg.ecra[0] || ''), r.reg.ecra);\n  }\n  {\n    const r = await correr(SRC, 'makeEsquivaModule', op([INIMIGO]), 1, (j) => { ligaE(j); semAdministrador(j); });\n    t.verifica('sem Administrador: nenhum pedido, conta o desmentido como sempre, e diz porquê',\n      r.vg === 0 && (desmentidas(r)['111'] || {}).falhas === 1 && r.reg.rotina.some((m) => /\\(sem Administrador\\)/.test(m)),\n      { vg: r.vg, d: desmentidas(r), rotina: r.reg.rotina });\n  }\n  {\n    const r = await correr(SRC, 'makeEsquivaModule', { respostas: [lista([INIMIGO])] }, 1, ligaE);\n    t.verifica('leitura global (nada na colecção Attack): um pedido só', r.vg === 1, r.vg);\n  }\n\n  t.secao('OS DOIS NA MESMA PASSAGEM');\n  {\n    const j = jogo(op([INIMIGO].concat(OUTROS))); carregarNucleo(SRC, j); ligaA(j); ligaE(j);\n    const reg = { ecra: [], rotina: [], discord: [] }; const c = S.contexto(j, reg);\n    await S.modulo(SRC, 'makeAlertasModule', j).mod.run(c);\n    await S.modulo(SRC, 'makeEsquivaModule', j).mod.run(c);\n    t.verifica('alertas + esquiva seguidos → 1 pedido à visão geral', j.pedidosVG() === 1, j.pedidosVG());\n  }\n  t.secao('RECLASSIFICAR');\n  {\n    /* Um ataque visto cedo parece rápido; mais tarde revela-se colonizador.\n     * A marca para o módulo dos feitiços tem de aparecer na mesma. */\n    const marca = (j) => {\n      try { return JSON.parse(j.localStorage.getItem('grepoAlertas_nc_v1') || '{}'); }\n      catch (e) { return {}; }\n    };\n    const INIMIGO_NC = Object.assign({}, INIMIGO, { id: 900, arrival_at: AGORA_S + 60 });\n    const r = await correr(SRC, 'makeAlertasModule',\n      Object.assign({ respostas: [lista([INIMIGO_NC])] }, naAttack(111)), 1, ligaA);\n    t.verifica('um ataque classificado como colonizador fica marcado para os feitiços',\n      Object.keys(marca(r.j)).length >= 0, marca(r.j));\n  }\n  t.fim();\n})().catch((e) => { console.error('O TESTE REBENTOU:', e); process.exit(2); });\n",
 "teste-apoio-botoes.js": "/* APOIO — reforçar e repor.\n *\n * \"Reforçar\" contava ENVIOS, e um envio era o pacote — que desapareceu com o\n * modo sem objectivo (5000): o botão deixou de mandar seja o que for.\n * \"Repor\" era o que ESTA conta perdeu, por isso nem aparecia na main quando\n * ela não tinha enviado nada. Agora: reforçar é tropa a mais, repor é encher\n * até ao objectivo. O código REAL do módulo.\n *\n *   node ferramentas/teste-apoio-botoes.js maestro.user.js\n */\nconst S = require('./simulador');\nconst { vm, funcao, tira, igual } = S;\nconst SRC = S.ficheiroDoMaestro();\nconst t = S.verificador('APOIO — REFORÇAR E REPOR');\nconst AP = 'function makeApoioModule(opts)';\n\nfunction montar(guardado) {\n  const loja = guardado ? { grepoApoio_reforcar_v1: JSON.stringify(guardado) } : {};\n  const escritos = [];\n  const ctx = {\n    armazem: { getItem: (k) => (k in loja ? loja[k] : null), setItem: (k, v) => { loja[k] = v; } },\n    seErroDeCodigo: () => {}, console, JSON, Object, Number, Math,\n    fbUrlM: () => 'https://falso', fbLerM: async () => ({}),\n    fbEscreverM: async (p, v) => { escritos.push(v); return { ok: true }; },\n    fbCaminhoPedidos: () => 'pedidos/pt125',\n  };\n  vm.createContext(ctx);\n  const api = vm.runInContext(funcao(SRC, '  function lerReforco() {', AP)\n    + funcao(SRC, '  function gravarReforco(d) {', AP)\n    + funcao(SRC, '  async function publicarPedido(tipo, alvoId, quanto) {', AP)\n    + '\\n({ ler: lerReforco, gravar: gravarReforco, publicar: publicarPedido })', ctx);\n  return { api, escritos, loja };\n}\n\n(async () => {\n  {\n    const m = montar();\n    m.api.gravar({ 5512: { sword: 500, bireme: 200 } });\n    t.verifica('o reforço guarda-se como tropa, por alvo',\n      igual(m.api.ler(), { 5512: { sword: 500, bireme: 200 } }), m.api.ler());\n  }\n  {\n    const m = montar({ 5512: { sword: 500 } });\n    await m.api.publicar('reforcar', 5512, { sword: 500, bireme: 200 });\n    const p = m.escritos[0].reforcar_5512;\n    t.verifica('o pedido viaja com as unidades, não com um número de envios',\n      igual(p.unidades, { sword: 500, bireme: 200 }) && p.tipo === 'reforcar' && p.alvo === 5512, p);\n  }\n  {\n    const m = montar();\n    await m.api.publicar('repor', 5512, 1);\n    const p = m.escritos[0].repor_5512;\n    t.verifica('o pedido de repor não leva unidades (é o objectivo que manda)',\n      p.tipo === 'repor' && p.unidades === null && p.quanto === 1, p);\n  }\n  {\n    /* O desconto: o que sai abate ao reforço pedido. */\n    const m = montar({ 5512: { sword: 500, bireme: 200 } });\n    const ctx2 = {\n      armazem: { getItem: () => JSON.stringify({ 5512: { sword: 500, bireme: 200 } }),\n        setItem: (k, v) => { ctx2.__ultimo = JSON.parse(v); } },\n      seErroDeCodigo: () => {}, console,\n      alvo: 5512, cargaFinal: { sword: 300, bireme: 200 },\n      lerReforco: m.api.ler, gravarReforco: (d) => { ctx2.__ultimo = d; },\n      Math, Number, Object, JSON,\n    };\n    vm.createContext(ctx2);\n    vm.runInContext(tira(SRC, '        try {\\n          const extra = lerReforco();\\n          const pedido = extra[alvo];',\n      '        } catch (e) { seErroDeCodigo(e, \\'Apoio\\'); }\\n'), ctx2);\n    t.verifica('o que sai desconta ao reforço; o que ficou por mandar mantém-se',\n      igual(ctx2.__ultimo, { 5512: { sword: 200 } }), ctx2.__ultimo);\n  }\n  t.fim();\n})().catch((e) => { console.error('O TESTE REBENTOU:', e); process.exit(2); });\n",
 "teste-apoio-painel.js": "/* APOIO — nomes em lote e total por alvo.\n *\n * O botão \"actualizar\" pedia o nome de cada alvo à vez: com uma lista grande\n * o servidor respondia 429, e o 429 trava o maestro inteiro. O `get_chunks`\n * aceita vários blocos, por isso vão num pedido só. E o painel passa a mostrar\n * a tropa TOTAL no alvo (todas as contas), não só a desta conta.\n *\n *   node ferramentas/teste-apoio-painel.js maestro.user.js\n */\nconst S = require('./simulador');\nconst { vm, funcao, igual } = S;\nconst SRC = S.ficheiroDoMaestro();\nconst t = S.verificador('APOIO — PAINEL');\nconst AP = 'function makeApoioModule(opts)';\n\n/* Alvos em duas ilhas: 9001/9002 no mesmo bloco do mapa, 9003 noutro. */\nfunction ambiente(frota) {\n  const pedidos = [];\n  const cidade = (id, ix, iy, dono) => ({ id, name: 'Cidade ' + id, player_name: dono, island_x: ix, island_y: iy });\n  const mUw = {\n    location: { origin: 'https://pt125.grepolis.com' },\n    Game: { csrfToken: 'TOK' },\n    ITowns: { towns: { 111: {} } },\n    GameData: { units: { sword: { name: 'espadachim' }, bireme: { name: 'birreme' } } },\n    fetch: async (url) => {\n      pedidos.push(String(url));\n      const j = JSON.parse(decodeURIComponent((String(url).match(/json=([^&]+)/) || [])[1] || '{}'));\n      const data = {};\n      (j.chunks || []).forEach((c, i) => {\n        const towns = {};\n        if (c.x === 25 && c.y === 25) { towns[9001] = cidade(9001, 500, 500, 'Vilão'); towns[9002] = cidade(9002, 502, 505, 'Outro'); }\n        if (c.x === 30 && c.y === 30) { towns[9003] = cidade(9003, 600, 600, 'Terceiro'); }\n        data[i] = { towns };\n      });\n      const corpo = JSON.stringify({ json: { data } });\n      return { status: 200, text: async () => corpo, json: async () => JSON.parse(corpo) };\n    },\n  };\n  const ctx = {\n    mUw, mWorld: 'pt125', CHUNK: 20, seErroDeCodigo: () => {}, console, setTimeout,\n    cacheCidades: {}, gravarNomes: () => {},\n    lerResposta: async (r) => JSON.parse(await r.text()),\n    coordenadasPorMovimentos: (id) => ({ 9001: { x: 500, y: 500 }, 9002: { x: 502, y: 505 }, 9003: { x: 600, y: 600 } }[id] || null),\n    fbUrlM: () => 'https://falso', fbLerM: async () => frota,\n  };\n  vm.createContext(ctx);\n  const txt = funcao(SRC, '  async function nomesEmLote(ids, townIdBase) {', AP)\n    + funcao(SRC, '  async function totaisNosAlvos() {', AP)\n    + '\\n({ nomesEmLote, totaisNosAlvos, cache: () => cacheCidades })';\n  return { api: vm.runInContext(txt, ctx), pedidos };\n}\n\nconst agora = Math.floor(Date.now() / 1000);\nconst FROTA = {\n  multi1: { quando: agora - 60, apoio: { alvos: { 9001: { u: { sword: 300, bireme: 20 } } } } },\n  multi2: { quando: agora - 120, apoio: { alvos: { 9001: { u: { sword: 200 } }, 9002: { u: { sword: 50 } } } } },\n  parada: { quando: agora - 7200, apoio: { alvos: { 9001: { u: { sword: 9999 } } } } },\n};\n\n(async () => {\n  {\n    const { api, pedidos } = ambiente(FROTA);\n    const n = await api.nomesEmLote([9001, 9002, 9003], 111);\n    t.verifica('três alvos em dois blocos → UM pedido ao mapa', pedidos.length === 1, pedidos.length);\n    t.verifica('... e descobre os três nomes', n === 3 && api.cache()[9001].nome === 'Cidade 9001'\n      && api.cache()[9003].jogador === 'Terceiro', api.cache());\n  }\n  {\n    const { api, pedidos } = ambiente(FROTA);\n    await api.nomesEmLote([9001], 111);\n    const antes = pedidos.length;\n    const n2 = await api.nomesEmLote([9001], 111);\n    t.verifica('um alvo já conhecido não custa pedido nenhum', n2 === 0 && pedidos.length === antes, pedidos.length);\n  }\n  {\n    const { api } = ambiente(FROTA);\n    const tt = await api.totaisNosAlvos();\n    t.verifica('soma as contas vivas em cada alvo', igual(tt.porAlvo['9001'], { sword: 500, bireme: 20 })\n      && igual(tt.porAlvo['9002'], { sword: 50 }), tt.porAlvo);\n    t.verifica('... e ignora uma conta calada há duas horas', tt.contas === 2 && tt.ok, tt);\n  }\n  {\n    const { api } = ambiente(null);\n    const tt = await api.totaisNosAlvos();\n    t.verifica('sem dados na frota: diz que leu, sem totais', tt.ok && !Object.keys(tt.porAlvo).length, tt);\n  }\n  /* QUANTOS ALVOS MAIS É QUE A TROPA EM CASA COBRE. */\n  {\n    /* O objectivo tem tropa terrestre: a conta precisa da população das\n     * unidades e dos transportes que a levam. */\n    const ctx = { Math, Number, Object, Infinity,\n      mUw: { GameData: { units: { sword: { population: 1 }, archer: { population: 1 },\n        hoplite: { population: 1 }, bireme: { is_naval: true, population: 1 } } } } };\n    vm.createContext(ctx);\n    const f = vm.runInContext(funcao(SRC, '  function quantosAlvosMais(casa, objetivo) {', AP) + '\\nquantosAlvosMais', ctx);\n    const obj = { sword: 3000, archer: 3000, hoplite: 3000, bireme: 1500 };\n    t.verifica('tropa para três alvos, travada pelos birremes',\n      igual(f({ sword: 12000, archer: 12000, hoplite: 12000, bireme: 5200, __capacidade: 999999 }, obj), { quantos: 3, limita: 'bireme' }),\n      f({ sword: 12000, archer: 12000, hoplite: 12000, bireme: 5200, __capacidade: 999999 }, obj));\n    t.verifica('sem tropa nenhuma: zero alvos', f({}, obj).quantos === 0);\n    t.verifica('falta uma unidade do objectivo: conta zero, e diz qual',\n      igual(f({ sword: 99999, archer: 99999, hoplite: 99999, __capacidade: 999999 }, obj), { quantos: 0, limita: 'bireme' }),\n      f({ sword: 99999, archer: 99999, hoplite: 99999, __capacidade: 999999 }, obj));\n    t.verifica('sem objectivo definido: não dá para contar', f({ sword: 100 }, {}) === null);\n    /* Sem barcos, a tropa terrestre não sai da ilha. */\n    t.verifica('tropa de sobra mas sem transportes: zero alvos, e diz que são eles',\n      igual(f({ sword: 99999, archer: 99999, hoplite: 99999, bireme: 99999 }, obj),\n        { quantos: 0, limita: 'transportes' }),\n      f({ sword: 99999, archer: 99999, hoplite: 99999, bireme: 99999 }, obj));\n    t.verifica('transportes para dois alvos, tropa para muitos: manda o menor',\n      f({ sword: 99999, archer: 99999, hoplite: 99999, bireme: 99999, __capacidade: 18000 }, obj).quantos === 2,\n      f({ sword: 99999, archer: 99999, hoplite: 99999, bireme: 99999, __capacidade: 18000 }, obj));\n    t.verifica('objectivo com zeros é ignorado',\n      f({ sword: 6000, __capacidade: 999999 }, { sword: 3000, archer: 0 }).quantos === 2,\n      f({ sword: 6000, __capacidade: 999999 }, { sword: 3000, archer: 0 }));\n  }\n  t.fim();\n})().catch((e) => { console.error('O TESTE REBENTOU:', e); process.exit(2); });\n",
 "teste-apoio-transportes.js": "/* APOIO — transportes só quando o alvo está noutra ilha.\n *\n * Na mesma ilha a tropa vai a pé e o jogo não pede transportes. O Apoio\n * pedia-os sempre, e uma cidade sem eles saltava: \"sem transportes para levar\n * a tropa; salto\". O código REAL do Apoio (as funções e as duas linhas onde se\n * decide), com as ilhas simuladas.\n *\n *   node ferramentas/teste-apoio-transportes.js maestro.user.js\n */\nconst S = require('./simulador');\nconst { vm, tira, funcao, igual } = S;\nconst SRC = S.ficheiroDoMaestro();\nconst t = S.verificador('APOIO — TRANSPORTES');\nconst APOIO = 'function makeApoioModule(opts)';\n\n/* As minhas cidades: 111 na ilha 100:100, 222 na 100:110. `transportes` diz\n * quantos transportes rápidos tem cada uma. */\nfunction montar(transportes) {\n  const ilhas = { 111: [100, 100], 222: [100, 110] };\n  const mUw = {\n    ITowns: {\n      towns: { 111: {}, 222: {} },\n      getTown: (id) => ({\n        getIslandCoordinateX: () => ilhas[id][0], getIslandCoordinateY: () => ilhas[id][1],\n        units: () => Object.assign({ sword: 500 }, (transportes || {})[id] ? { small_transporter: transportes[id] } : {}),\n        researches: () => ({ attributes: {} }),\n      }),\n    },\n    GameData: { units: { sword: { population: 1 } } },\n  };\n  const txt = tira(SRC, '  const CAPACIDADE = {', \"const TERRESTRES = ['sword', 'slinger', 'archer', 'hoplite', 'rider', 'chariot', 'catapult'];\", APOIO)\n    + '\\n' + funcao(SRC, '  function temBeliche(townId) {', APOIO)\n    + funcao(SRC, '  function popDaUnidade(u) {', APOIO)\n    + funcao(SRC, '  function juntarTransportes(townId, pacote, c) {', APOIO)\n    + funcao(SRC, '  function mesmaIlhaQueOAlvo(townId, alvoId) {', APOIO)\n    + '\\nfunction decidir(t, alvo, carga, c) {\\n'\n    + tira(SRC, '        const aPe = mesmaIlhaQueOAlvo(t.id, alvo) === true;', 'juntarTransportes(t.id, carga, c);\\n', APOIO)\n    + '        return cargaFinal;\\n}\\n({ decidir, mesmaIlhaQueOAlvo })';\n  /* Alvos de outros jogadores: um na ilha da 111, outro noutra ilha. */\n  const ctx = { mUw, seErroDeCodigo: () => {},\n    cacheCidades: { 9001: { nome: 'Vizinha', ilha: { x: 100, y: 100 } }, 9002: { nome: 'Longe', ilha: { x: 300, y: 300 } } } };\n  vm.createContext(ctx);\n  return vm.runInContext(txt, ctx);\n}\nconst temAlgo = (carga) => Object.keys(carga).some((u) => (Number(carga[u]) || 0) > 0);\n\n(async () => {\n  {\n    const a = montar();\n    t.verifica('alvo de outro jogador na mesma ilha → mesma ilha', a.mesmaIlhaQueOAlvo(111, 9001) === true);\n    t.verifica('alvo de outro jogador noutra ilha → outra ilha', a.mesmaIlhaQueOAlvo(111, 9002) === false);\n    t.verifica('alvo que é cidade minha noutra ilha → outra ilha', a.mesmaIlhaQueOAlvo(111, 222) === false);\n    t.verifica('alvo de que não se sabe a ilha → null (fica como estava)', a.mesmaIlhaQueOAlvo(111, 9999) === null);\n  }\n  {\n    const a = montar();   // sem transportes nenhuns\n    const c = a.decidir({ id: 111 }, 9001, { sword: 100 }, {});\n    t.verifica('sem transportes, alvo na mesma ilha: a tropa vai a pé', temAlgo(c) && igual(c, { sword: 100 }), c);\n    const l = a.decidir({ id: 111 }, 9002, { sword: 100 }, {});\n    t.verifica('sem transportes, alvo noutra ilha: não há como levar (salta, como antes)', !temAlgo(l), l);\n    const d = a.decidir({ id: 111 }, 9999, { sword: 100 }, {});\n    t.verifica('sem transportes, ilha do alvo desconhecida: como antes (salta)', !temAlgo(d), d);\n  }\n  {\n    const a = montar({ 111: 20 });\n    const l = a.decidir({ id: 111 }, 9002, { sword: 100 }, {});\n    t.verifica('com transportes, alvo noutra ilha: juntam-se os transportes', (l.small_transporter || 0) > 0 && l.sword === 100, l);\n    const c = a.decidir({ id: 111 }, 9001, { sword: 100 }, {});\n    t.verifica('com transportes, alvo na mesma ilha: não se levam transportes', !c.small_transporter && c.sword === 100, c);\n  }\n  t.fim();\n})().catch((e) => { console.error('O TESTE REBENTOU:', e); process.exit(2); });\n",
 "teste-cancelamento.js": "/* CANCELAR UM COMANDO — o jogo diz se o apagou mesmo.\n *\n * A resposta do `cancelCommand` traz `command_deleted` (espia, 11/09). Um\n * `false` explícito é uma recusa silenciosa: sem `error`, passava por\n * cancelado e a tropa seguia à mesma. Onde o campo não vem, fica como estava.\n * O `post` REAL do Encaixe e da Esquiva, e o cancelamento REAL do Apoio.\n *\n *   node ferramentas/teste-cancelamento.js maestro.user.js\n */\nconst S = require('./simulador');\nconst { vm, tira, funcao } = S;\nconst SRC = S.ficheiroDoMaestro();\nconst t = S.verificador('CANCELAR COMANDOS');\n\nfunction ambiente(resposta) {\n  const corpo = JSON.stringify({ json: resposta });\n  return {\n    mUw: {\n      location: { origin: 'https://pt125.grepolis.com' },\n      Game: { csrfToken: 'TOK' },\n      fetch: async () => ({ status: 200, text: async () => corpo, json: async () => JSON.parse(corpo) }),\n    },\n    window: {}, seErroDeCodigo: () => {}, console,\n    lerResposta: async (r) => JSON.parse(await r.text()),\n    aplicarNotificacoes: () => {},\n  };\n}\n\n/* O `post` do Encaixe (o segundo do ficheiro) e o da Esquiva. */\nfunction posts(qual, resposta) {\n  const ini = SRC.indexOf(qual === 'encaixe' ? 'MÓDULO: ENCAIXE DE COMANDOS' : 'MÓDULO: ESQUIVA DE ATAQUES');\n  const a = SRC.indexOf('  async function post(url, payload) {', ini);\n  const txt = SRC.slice(a, SRC.indexOf('\\n  }\\n', a) + 4) + '\\npost';\n  const ctx = ambiente(resposta);\n  vm.createContext(ctx);\n  return vm.runInContext(txt, ctx)('https://x', {});\n}\n\n/* O cancelamento do Apoio devolve true/false. */\nfunction apoio(resposta) {\n  const txt = funcao(SRC, '  async function cancelarOuRetirar(mov, alvoId) {') + '\\ncancelarOuRetirar';\n  const ctx = ambiente(resposta);\n  ctx.registarEnvio = () => {};\n  vm.createContext(ctx);\n  return vm.runInContext(txt, ctx)({ command_id: 7, home_town_id: 111 }, 999);\n}\n\n(async () => {\n  const CASOS = [\n    ['o jogo apagou o comando', { success: 'O comando foi cancelado.', command_deleted: true }, true],\n    /* Cancelar tropa a caminho transforma o comando num regresso: o jogo\n     * responde `success` com `command_deleted: false`. É sucesso. */\n    ['tropa a caminho: vira regresso (success + command_deleted false)',\n      { success: 'O comando foi cancelado.', command_deleted: false }, true],\n    ['recusa silenciosa (command_deleted false SEM success)', { command_deleted: false }, false],\n    ['resposta sem o campo: fica como estava', { success: 'O comando foi cancelado.' }, true],\n    ['erro do jogo', { error: 'O comando não existe.' }, false],\n  ];\n  for (const [nome, resp, esperado] of CASOS) {\n    for (const qual of ['encaixe', 'esquiva']) {\n      const r = await posts(qual, resp);\n      t.verifica(`${qual}: ${nome}`, r.ok === esperado, r);\n    }\n    const r2 = await apoio(resp);\n    t.verifica(`apoio: ${nome}`, r2 === esperado, r2);\n  }\n  {\n    const r = await posts('encaixe', { command_deleted: false });\n    t.verifica('e diz porquê', /não apagou o comando nem confirmou/.test(r.msg), r.msg);\n  }\n  t.fim();\n})().catch((e) => { console.error('O TESTE REBENTOU:', e); process.exit(2); });\n",
 "teste-captcha.js": "/* CAPTCHA NO ECRÃ — o núcleo pára o ciclo E avisa no Discord.\n *\n * O troço REAL do ciclo (tick) e o `avisarCaptcha` REAL, com o relógio\n * simulado. Com o ciclo parado param os módulos que avisavam; é o núcleo que\n * tem de avisar — logo, e depois de meia em meia hora.\n *\n *   node ferramentas/teste-captcha.js maestro.user.js\n */\nconst S = require('./simulador');\nconst { vm, tira, igual } = S;\nconst SRC = S.ficheiroDoMaestro();\nconst t = S.verificador('CAPTCHA NO ECRÃ');\n\nasync function simular(passos) {\n  let agora = 1_800_000_000_000;\n  let captcha = null;\n  const discord = [], registo = [], loja = {};\n  const ctx = {\n    uw: { Game: { player_name: 'MultiX', world_id: 'pt126' },\n      __maestroAvisarDiscord: async (tipo, a) => { discord.push({ tipo, campos: a.campos }); } },\n    localStorage: { getItem: (k) => (k in loja ? loja[k] : null), setItem: (k, v) => { loja[k] = String(v); } },\n    log: (m, x) => registo.push(x), captchaNoEcra: () => captcha,\n  };\n  ctx.Date = new Proxy(Date, { get: (tt, p) => (p === 'now' ? () => agora : tt[p]) });\n  vm.createContext(ctx);\n  const txt = tira(SRC, \"  const CAPTCHA_AVISO_KEY = 'grepoMaestro_captchaAvisado_v1';\", 'try { uw.__maestroAvisarCaptcha = avisarCaptcha; } catch (e) {}')\n    + '\\nlet captchaNoEcraDesde = 0, captchaAvisadoEm = 0, captchaIgnorarAte = 0;\\nasync function passo() {\\n'\n    + tira(SRC, '    const vistoNoEcra = (Date.now() < captchaIgnorarAte) ? null : captchaNoEcra();',\n      \"      log('core', '▶️ O captcha saiu do ecrã — retomo o trabalho.');\\n    }\\n\")\n    + \"  return 'segue';\\n}\\npasso\";\n  const passo = vm.runInContext(txt, ctx);\n  const out = [];\n  for (const p of passos) {\n    agora += (p.min || 0) * 60000;\n    captcha = p.captcha ? { desc: 'iframe 300×150 em 400,300' } : null;\n    const r = await passo();\n    await new Promise((res) => setImmediate(res));\n    out.push({ parado: r !== 'segue', discord: discord.length });\n  }\n  return { out, discord, registo };\n}\n\n(async () => {\n  const d = await simular([{ min: 0 }, { min: 1, captcha: true }, { min: 10, captcha: true }, { min: 10, captcha: true },\n    { min: 11, captcha: true }, { min: 2, captcha: true }, { min: 3 }]);\n  t.verifica('com o captcha no ecrã, o ciclo pára', igual(d.out.slice(0, 5).map((x) => x.parado), [false, true, true, true, false]), d.out);\n  t.verifica('avisa no Discord logo que o vê', d.out[1].discord === 1, d.out);\n  t.verifica('... com a conta e o mundo', /MultiX/.test(JSON.stringify(d.discord[0])) && /pt126/.test(JSON.stringify(d.discord[0])), d.discord[0]);\n  t.verifica('... não repete aos 10 e 20 min', d.out[2].discord === 1 && d.out[3].discord === 1, d.out);\n  t.verifica('... e lembra outra vez passada meia hora', d.out[4].discord === 2, d.out);\n  t.verifica('o registo do ecrã diz que parou e que retomou', d.registo.some((x) => /Há um captcha no ecrã/.test(x))\n    && d.registo.some((x) => /30 min parado/.test(x)), d.registo);\n  t.fim();\n})().catch((e) => { console.error('O TESTE REBENTOU:', e); process.exit(2); });\n",
 "teste-colonizador.js": "/* DETECTAR COLONIZADOR — sem a hora de partida.\n *\n * Os ataques dos outros vêm SEMPRE com `started_at: 0` (confirmado em jogo,\n * 12/09), por isso a viagem é estimada e a velocidade sai errada — 37 numa\n * leitura em que o limite do colonizador era 11,5. O que decide sem precisar\n * da partida é o tempo que FALTA: se ainda faltam T horas para percorrer D, a\n * velocidade não pode passar de D/T.\n *\n * As velocidades do jogo já vêm com o factor do mundo (pt126, ×3: colonizador\n * 9 = 3×3, birreme 45 = 15×3), por isso a comparação é na mesma escala.\n *\n *   node ferramentas/teste-colonizador.js maestro.user.js\n */\nconst S = require('./simulador');\nconst { vm, funcao, tira } = S;\nconst SRC = S.ficheiroDoMaestro();\nconst t = S.verificador('COLONIZADOR');\n\nfunction montar() {\n  const ctx = {\n    uw: { GameData: { powers: { unit_movement_boost: { meta_defaults: { percent: 30 } } }, units: {\n      colonize_ship: { speed: 9, is_naval: true },\n      bireme: { speed: 45, is_naval: true },\n      small_transporter: { speed: 45, is_naval: true },\n      attack_ship: { speed: 60, is_naval: true },\n      sword: { speed: 20 },\n    } } },\n    Math, Number, Object,\n    localStorage: { getItem: () => null },\n  };\n  vm.createContext(ctx);\n  /* Do início das constantes até ao fim do `pareceColonizadorNC`. */\n  const a = SRC.indexOf('  const FOLGA_MEDICAO_NC =');\n  const b = SRC.indexOf('  try {\\n    uw.__maestroNC = {', a);\n  return vm.runInContext(SRC.slice(a, b)\n    + '\\n({ parece: pareceColonizadorNC, limite: limiteColonizador })', ctx);\n}\n\n(async () => {\n  const api = montar();\n  /* Todos os bónus juntos: cartografia, farol, navegar, feitiço e 4 sereias. */\n  const TECTO = 9 * 1.10 * 1.15 * 1.10 * 1.30 * Math.pow(1.02, 4);\n  t.verifica('o tecto do colonizador junta cartografia, farol, navegar, feitiço e sereias',\n    Math.abs(api.limite() - TECTO) < 0.05, { limite: api.limite(), esperado: TECTO });\n  {\n    const r = api.parece(9, false);\n    t.verifica('velocidade igual à do colonizador: é colonizador, com certeza', r.nc && r.certo, r);\n  }\n  {\n    const r = api.parece(45, false);\n    t.verifica('velocidade de birreme: não é colonizador', !r.nc, r);\n  }\n  {\n    /* O caso real: velocidade estimada alta (37), mas o tempo que falta prova\n     * que não pode andar a mais de 10. */\n    const r = api.parece(37, false, 10);\n    t.verifica('o que falta da viagem prova colonizador, mesmo com a estimativa alta',\n      r.nc && r.certo && /já não dá para mais nada/.test(r.porque), r);\n  }\n  {\n    const r = api.parece(10, false, 50);\n    t.verifica('10 é a velocidade do colonizador com cartografia: é colonizador, com certeza',\n      r.nc && r.certo, r);\n  }\n  {\n    /* Abaixo do limite, mas sem bater certo com nenhuma unidade nem com os\n     * bónus conhecidos: suspeita, não certeza. */\n    const r = api.parece(6, false);\n    t.verifica('lento de mais para tudo menos o colonizador: suspeita', r.nc && !r.certo, r);\n  }\n  {\n    const r = api.parece(0, false);\n    t.verifica('sem velocidade nenhuma: não afirma nada', !r.nc && !r.certo, r);\n  }\n  /* O ELMO DA INVISIBILIDADE esconde os primeiros 10% da viagem, e nada na\n   * resposta do jogo o denuncia nos ataques dos outros: a velocidade medida\n   * vem ~11% inflada. */\n  {\n    /* Acima do tecto e fora da folga de medição, mas dentro da margem do\n     * elmo (tecto ÷ 0,9). */\n    const r = api.parece(TECTO * 1.10, false);\n    t.verifica('acima do limite mas dentro da margem do elmo: suspeita, não exclusão',\n      r.nc && !r.certo && /elmo/.test(r.porque), r);\n  }\n  {\n    const r = api.parece(TECTO * 1.5, false);\n    t.verifica('bem acima da margem do elmo: não é colonizador', !r.nc && r.certo, r);\n  }\n  {\n    /* O máximo pelo tempo que falta SÓ SERVE PARA ACUSAR: um máximo alto não\n     * prova nada, porque a velocidade real pode ser qualquer uma abaixo. */\n    const r = api.parece(9, false, 999);\n    t.verifica('máximo alto não desfaz uma certeza medida', r.nc && r.certo, r);\n  }\n  /* O FEITIÇO DE MOVIMENTO (+30%, lido do jogo) entra nas combinações. */\n  {\n    /* O \"navegar\" (+10%) só acelera o colonizador: uma velocidade que só ele\n     * explica tem de ser reconhecida. */\n    const r = api.parece(9 * 1.10, false);\n    t.verifica('velocidade que só o navegar explica: é colonizador', r.nc && r.certo, r);\n  }\n  {\n    /* 9 × 1,30 = 11,7: um colonizador só com o feitiço. */\n    const r = api.parece(11.7, false);\n    t.verifica('velocidade que só o feitiço explica: é colonizador, com certeza',\n      r.nc && r.certo && /colonizador/.test(r.porque), r);\n  }\n  {\n    /* 9 × 1,10 × 1,15 × 1,30 = 14,8: tudo junto. */\n    const r = api.parece(TECTO, false);\n    t.verifica('colonizador com tudo: continua a ser apanhado', r.nc, r);\n  }\n  {\n    const r = api.parece(45, false);\n    t.verifica('birreme continua fora de suspeita, mesmo com a folga maior', !r.nc, r);\n  }\n  /* O VISTO DO MUNDO OLIMPO acrescenta o grande templo (+15%). */\n  {\n    const comOlimpo = (() => {\n      const ctx2 = {\n        uw: { GameData: { units: { colonize_ship: { speed: 9, is_naval: true }, bireme: { speed: 45, is_naval: true } },\n          powers: { unit_movement_boost: { meta_defaults: { percent: 30 } } } } },\n        Math, Number, Object, localStorage: { getItem: () => '1' },\n      };\n      vm.createContext(ctx2);\n      const a = SRC.indexOf('  const FOLGA_MEDICAO_NC =');\n      const b = SRC.indexOf('  try {\\n    uw.__maestroNC = {', a);\n      return vm.runInContext(SRC.slice(a, b) + '\\n({ limite: limiteColonizador, parece: pareceColonizadorNC })', ctx2);\n    })();\n    t.verifica('mundo Olimpo: o tecto sobe 15%',\n      Math.abs(comOlimpo.limite() - TECTO * 1.15) < 0.05,\n      { olimpo: comOlimpo.limite(), normal: TECTO });\n    t.verifica('... e uma velocidade que só o templo explica passa a ser apanhada',\n      comOlimpo.parece(TECTO * 1.14, false).nc && !api.parece(TECTO * 1.14, false).nc);\n  }\n  t.fim();\n})().catch((e) => { console.error('O TESTE REBENTOU:', e); process.exit(2); });\n",
 "teste-colonizadores-revoltas.js": "/* APOIO (revoltas), FUNDAÇÃO e EXPANSÃO — a visão geral pelo núcleo.\n *\n * Apoio: cópia partilhada. Fundação e Expansão: sempre fresca, porque um\n * colonizador enviado agora tem de contar já. E \"não consegui ler\" nunca é\n * \"nenhum colonizador a caminho\": a fundação não funda, a barreira não deixa\n * sair nenhum.\n *\n *   node ferramentas/teste-colonizadores-revoltas.js maestro.user.js\n */\nconst S = require('./simulador');\nconst { AGORA_S, vm, tira, funcao, jogo, carregarNucleo, semAdministrador, correr, ligar, lista, ERRO, LIMITADO,\n  igual } = S;\nconst SRC = S.ficheiroDoMaestro();\n\nconst t = S.verificador('APOIO, FUNDAÇÃO, EXPANSÃO');\n\nasync function apoio(j) {\n  const seg = tira(SRC, '            const temAdm = (() => {', 'const visaoOk = !!vg.ok;');\n  const porque = tira(SRC, \"              const porque = !temAdm ? 'esta conta não tem Administrador'\", ';\\n');\n  const ctx = { mUw: j.win, window: j.win, console };\n  vm.createContext(ctx);\n  return vm.runInContext(`(async () => {\\n${seg}\\n${porque}\\nreturn { cmdsLidos, visaoOk, porque }; })()`, ctx);\n}\nasync function fundacao(j) {\n  const f = tira(SRC, \"  let razaoColonizadores = '';\", '\\n    return out;\\n  }\\n');\n  const ctx = { mUw: j.win, window: j.win, console, seErroDeCodigo: () => {}, coordenadasDoLinkDestino: () => null };\n  vm.createContext(ctx);\n  const r = await vm.runInContext(f + '\\nilhasComColonizadorAcaminho(111)', ctx);\n  return { r, razao: vm.runInContext('razaoColonizadores', ctx) };\n}\nfunction expansao(j) {\n  const txt = tira(SRC, '  const jogo = () => (typeof unsafeWindow', '\\n')\n    + tira(SRC, '  let colonizacoesQuando = 0;', '\\n')\n    + funcao(SRC, '  async function refrescarColonizacoes() {')\n    + tira(SRC, '  function podeFundarNaIlha(uw, ctx, x, y) {', \"\\n    return { pode: true, porque: '' };\\n  }\\n\")\n    + '\\n({ refrescar: refrescarColonizacoes, pode: (x, y) => podeFundarNaIlha(window, '\n    + '{ getMyTowns: () => [{ id: 111 }, { id: 222 }] }, x, y) })';\n  const loja = {};\n  const ctx = { window: j.win, console, seErroDeCodigo: () => {},\n    localStorage: { getItem: (k) => loja[k] || null, setItem: (k, v) => { loja[k] = v; } } };\n  vm.createContext(ctx);\n  return vm.runInContext(txt, ctx);\n}\n\nconst REVOLTAS = [\n  { id: 'revolt_901', type: 'revolt', started_at: AGORA_S + 3000, origin_town_id: 9001, destination_town_id: 222, arrival_at: AGORA_S + 9000 },\n  { id: 902, type: 'attack', started_at: 0, origin_town_id: 9002, destination_town_id: 111, arrival_at: AGORA_S + 500 },\n];\nconst COLONO = { id: 'colonization_5120', type: 'colonization', origin_town_id: 111, island_x: 365, island_y: 460,\n  number_on_island: 1, arrival_at: AGORA_S + 4000 };\nconst COLONO_FEITO = Object.assign({}, COLONO, { id: 'colonization_5121', island_x: 300, island_y: 300,\n  colonization_finished_at: AGORA_S - 10 });\n\n(async () => {\n  t.secao('APOIO — revoltas');\n  {\n    const j = jogo({ respostas: [lista(REVOLTAS)] }); carregarNucleo(SRC, j);\n    const d = await apoio(j);\n    t.verifica('leitura boa: a lista toda', d.visaoOk && d.cmdsLidos.length === 2, d);\n  }\n  {\n    const j = jogo({ respostas: [ERRO] }); carregarNucleo(SRC, j);\n    const d = await apoio(j);\n    t.verifica('erro do jogo: leitura falhada (não é \"nenhuma revolta\"), e diz porquê', !d.visaoOk && d.cmdsLidos === null\n      && d.porque === 'Ocorreu um erro.', d);\n  }\n  {\n    const j = jogo({ respostas: [LIMITADO] }); carregarNucleo(SRC, j);\n    let travou = 0; j.win.__maestroTravar = () => { travou++; };\n    const d = await apoio(j);\n    t.verifica('429: leitura falhada, e o núcleo trava', !d.visaoOk && travou === 1, { d, travou });\n  }\n  {\n    const j = jogo({ respostas: [lista(REVOLTAS)] }); carregarNucleo(SRC, j); semAdministrador(j);\n    const d = await apoio(j);\n    t.verifica('sem Administrador: nenhum pedido, e diz porquê', !d.visaoOk && j.pedidosVG() === 0 && /não tem Administrador/.test(d.porque), d);\n  }\n  {\n    const j = jogo({ respostas: [lista(REVOLTAS)] }); carregarNucleo(SRC, j);\n    await j.win.__maestroVisaoGeral();\n    const d = await apoio(j);\n    t.verifica('com uma cópia recente: usa-a, sem pedido novo', d.visaoOk && j.pedidosVG() === 1, j.pedidosVG());\n  }\n\n  t.secao('FUNDAÇÃO — colonizadores em viagem');\n  {\n    const j = jogo({ respostas: [lista([COLONO, COLONO_FEITO])] }); carregarNucleo(SRC, j);\n    const d = await fundacao(j);\n    t.verifica('\"365:460\", como quem chama procura; o que já fundou fica de fora', d.r.has('365:460') && d.r.size === 1, [...d.r]);\n  }\n  {\n    const j = jogo({ respostas: [lista([]), lista([COLONO])] }); carregarNucleo(SRC, j);\n    await j.win.__maestroVisaoGeral();\n    const d = await fundacao(j);\n    t.verifica('com uma cópia de antes do envio: vai ao servidor e vê o colonizador', d.r && d.r.has('365:460') && j.pedidosVG() === 2,\n      { r: d.r && [...d.r], pedidos: j.pedidosVG() });\n  }\n  {\n    const j = jogo({ respostas: [ERRO] }); carregarNucleo(SRC, j);\n    const d = await fundacao(j);\n    t.verifica('leitura falhada: null (não funda nesta passagem), com a razão', d.r === null && d.razao === 'Ocorreu um erro.', d);\n  }\n  {\n    const j = jogo({ respostas: [lista([COLONO])] }); carregarNucleo(SRC, j); semAdministrador(j);\n    const d = await fundacao(j);\n    t.verifica('sem Administrador: como sempre (vazio), sem pedido', d.r && d.r.size === 0 && j.pedidosVG() === 0, d);\n  }\n\n  t.secao('EXPANSÃO — a lista e a barreira');\n  {\n    const j = jogo({ respostas: [lista([COLONO, COLONO_FEITO])] }); carregarNucleo(SRC, j);\n    const e = expansao(j); await e.refrescar();\n    t.verifica('a lista dos que vão a caminho', igual(j.win.__maestroColonizacoesEmCurso.map((x) => x.id), ['colonization_5120']),\n      j.win.__maestroColonizacoesEmCurso);\n    t.verifica('a barreira trava a ilha com colonizador e deixa as outras', !e.pode(365, 460).pode && e.pode(500, 500).pode,\n      [e.pode(365, 460), e.pode(500, 500)]);\n    await e.refrescar();\n    t.verifica('não volta a perguntar antes de um minuto', j.pedidosVG() === 1, j.pedidosVG());\n  }\n  {\n    const j = jogo({ respostas: [ERRO, lista([])] }); carregarNucleo(SRC, j);\n    const e = expansao(j); await e.refrescar();\n    const p = e.pode(365, 460);\n    t.verifica('leitura falhada: a barreira não deixa sair nenhum, e diz porquê', p.pode === false\n      && /não consegui ler os colonizadores em viagem \\(Ocorreu um erro\\.\\)/.test(p.porque), p);\n    await e.refrescar();\n    t.verifica('... na passagem seguinte volta a ler e, lida, deixa sair', e.pode(500, 500).pode === true && j.pedidosVG() === 2,\n      { p: e.pode(500, 500), pedidos: j.pedidosVG() });\n  }\n  {\n    const j = jogo({ respostas: [lista([COLONO])] }); carregarNucleo(SRC, j); semAdministrador(j);\n    const e = expansao(j); await e.refrescar();\n    t.verifica('sem Administrador: como sempre (lista vazia, a barreira deixa), sem pedido',\n      e.pode(365, 460).pode === true && igual(j.win.__maestroColonizacoesEmCurso, []) && j.pedidosVG() === 0);\n  }\n  {\n    const j = jogo({ respostas: [lista([]), lista([COLONO])] }); carregarNucleo(SRC, j);\n    await j.win.__maestroVisaoGeral();\n    const e = expansao(j); await e.refrescar();\n    t.verifica('com uma cópia de antes do envio: vai ao servidor e trava a ilha', e.pode(365, 460).pode === false && j.pedidosVG() === 2);\n  }\n  t.fim();\n})().catch((e) => { console.error('O TESTE REBENTOU:', e); process.exit(2); });\n",
 "teste-demoras.js": "/* AS DEMORAS QUE O JOGO DÁ — comparar tempo com tempo.\n *\n * A janela de atacar devolve, para o alvo escolhido, quanto demora CADA\n * unidade, já com a distância, a velocidade do mundo e os bónus (visto em\n * jogo, 14/09: espadachim 625 s, colonizador 793 s…). É a única fonte na\n * MESMA ILHA, onde a distância entre ilhas é zero e não há velocidade para\n * medir.\n *\n *   node ferramentas/teste-demoras.js maestro.user.js\n */\nconst S = require('./simulador');\nconst { vm, tira, funcao } = S;\nconst SRC = S.ficheiroDoMaestro();\nconst t = S.verificador('DEMORAS');\n\nfunction montar(resposta) {\n  const pedidos = [];\n  const loja = {};\n  const corpo = JSON.stringify(resposta || {});\n  const ctx = {\n    uw: {\n      location: { origin: 'https://pt126.grepolis.com' }, Game: { csrfToken: 'TOK' },\n      GameData: {\n        units: { sword: { speed: 26.4 }, hoplite: { speed: 19.8 },\n          colonize_ship: { speed: 9, is_naval: true }, bireme: { speed: 49.5, is_naval: true } },\n        powers: { unit_movement_boost: { meta_defaults: { percent: 30 } } },\n      },\n      fetch: async (u) => { pedidos.push(String(u)); return { status: 200, text: async () => corpo }; },\n    },\n    localStorage: { getItem: (k) => (k in loja ? loja[k] : null), setItem: (k, v) => { loja[k] = v; } },\n    servidorTravado: () => false,\n    lerRespostaComum: async (r) => JSON.parse(await r.text()),\n    Math, Number, Object, JSON, Promise, Date, encodeURIComponent,\n  };\n  vm.createContext(ctx);\n  const a = SRC.indexOf('  const FOLGA_MEDICAO_NC =');\n  const b = SRC.indexOf('  try {\\n    uw.__maestroDemoras = {', a);\n  vm.runInContext(SRC.slice(a, b) + '\\n({})', ctx);\n  return { ctx, pedidos, loja };\n}\n\n/* A janela real, com os números de 14/09. */\nconst JANELA = { json: { json: { runtime_setup_time: 300, units: {\n  sword: { duration: 625, speed: 26.4 },\n  hoplite: { duration: 734, speed: 19.8 },\n  colonize_ship: { duration: 793, speed: 9 },\n  bireme: { duration: 473, speed: 49.5 },\n} } } };\n\n(async () => {\n  {\n    const m = montar(JANELA);\n    const d = await m.ctx.demorasPara(111, 999);\n    t.verifica('lê as demoras da janela de atacar', d && d.u.colonize_ship === 793 && d.prep === 300, d);\n    t.verifica('... com um pedido só', m.pedidos.length === 1, m.pedidos.length);\n    const d2 = await m.ctx.demorasPara(111, 999);\n    t.verifica('... e não repete o pedido: fica guardado', m.pedidos.length === 1 && d2.u.sword === 625);\n  }\n  {\n    const m = montar(JANELA);\n    const d = await m.ctx.demorasPara(111, 999);\n    const r = m.ctx.unidadesQueExplicamPorTempo(d, 793);\n    t.verifica('uma viagem de 793 s: o colonizador sem bónus explica-a',\n      r.some((x) => x.id === 'colonize_ship'), r.map((x) => x.id));\n  }\n  {\n    const m = montar(JANELA);\n    const d = await m.ctx.demorasPara(111, 999);\n    const r = m.ctx.unidadesQueExplicamPorTempo(d, 625);\n    /* 625 s é o tempo do espadachim — mas um colonizador com cartografia,\n     * farol, navegar e sereias também lá chega. Ambos explicam, logo fica a\n     * dúvida: é o resultado honesto, e o lado seguro. */\n    t.verifica('625 s: o espadachim explica, mas o colonizador com bónus também — fica a dúvida',\n      r.some((x) => x.id === 'sword') && r.some((x) => x.id === 'colonize_ship'), r.map((x) => x.id));\n    t.verifica('... e o espadachim é a explicação mais próxima', r[0].id === 'sword', r[0]);\n  }\n  {\n    /* Colonizador com feitiço: 300 + (793-300)/1,30 = 679 s. */\n    const m = montar(JANELA);\n    const d = await m.ctx.demorasPara(111, 999);\n    const r = m.ctx.unidadesQueExplicamPorTempo(d, 679);\n    t.verifica('colonizador com o feitiço: continua a ser apanhado',\n      r.some((x) => x.id === 'colonize_ship'), r);\n  }\n  {\n    const m = montar(JANELA);\n    const d = await m.ctx.demorasPara(111, 999);\n    const r = m.ctx.unidadesQueExplicamPorTempo(d, 120);\n    t.verifica('depressa de mais para tudo: nada explica', r.length === 0, r);\n  }\n  {\n    const m = montar({ json: { json: { units: {} } } });\n    const d = await m.ctx.demorasPara(111, 999);\n    t.verifica('resposta sem demoras: devolve null (não inventa)', d === null, d);\n  }\n  t.fim();\n})().catch((e) => { console.error('O TESTE REBENTOU:', e); process.exit(2); });\n",
 "teste-deuses-minimo.js": "/* DEUSES — o mínimo do jogo é em HABITANTES.\n *\n * \"Uma tropa de ataque tem de ser constituída pelo menos por 86 habitantes.\"\n * O módulo comparava CONTAGENS: 36 enviados contavam 36, quando valem 3 de\n * população cada (108). Cidades que já cumpriam o mínimo juntavam espadachins\n * à toa e, sem eles, ficavam à espera — visto em jogo (14/09, 34.3 e 34.4).\n *\n *   node ferramentas/teste-deuses-minimo.js maestro.user.js\n */\nconst S = require('./simulador');\nconst { vm, tira } = S;\nconst SRC = S.ficheiroDoMaestro();\nconst t = S.verificador('DEUSES — MÍNIMO');\n\n/* O troço real da decisão, com o mínimo, os enviados e os espadachins. */\nfunction decidir({ minimo, quantos, swords }) {\n  const reg = [];\n  const ctx = {\n    mUw: {\n      GameData: { units: { godsent: { population: 3 }, sword: { population: 1 } } },\n      ITowns: { getTown: () => ({ units: () => ({ sword: swords }) }) },\n    },\n    UNIDADE_ENVIADO: 'godsent',\n    minimoAprendido: () => minimo,\n    t: { id: 111, name: 'Cidade' },\n    quantos,\n    ctx: { log: (m) => reg.push(String(m)), logRotina: (m) => reg.push(String(m)) },\n    Math, Number,\n  };\n  vm.createContext(ctx);\n  /* Do comentário até ao fim do bloco do mínimo (o `}` que fecha o `if`). */\n  const i = SRC.indexOf('      /* O MÍNIMO DO JOGO É EM HABITANTES, NÃO EM UNIDADES.');\n  const fim = SRC.indexOf('\\n      /* VÁRIOS ATAQUES EM CURSO SÃO PERMITIDOS.', i);\n  const corpo = SRC.slice(i, fim);\n  /* `continue` só vale dentro de um ciclo: embrulha-se num. */\n  /* `escudoExtra` é `let` dentro do ciclo: leva-se para fora numa variável\n   * do contexto. */\n  vm.runInContext('var resultado = null;\\nfor (let i = 0; i < 1; i++) {\\n' + corpo\n    + '\\n  resultado = escudoExtra;\\n}', ctx);\n  return { escudoExtra: ctx.resultado, reg };\n}\n\n(async () => {\n  {\n    /* O caso real: 36 enviados = 108 habitantes, mínimo 80. Chega de sobra. */\n    const r = decidir({ minimo: 80, quantos: 36, swords: 44 });\n    t.verifica('36 enviados (108 hab.) com mínimo 80: ataca sem espadachins nenhuns',\n      r.escudoExtra === 0 && !r.reg.some((x) => /espero/.test(x)), r);\n  }\n  {\n    /* 20 enviados = 60 habitantes, mínimo 86: faltam 26 espadachins. */\n    const r = decidir({ minimo: 86, quantos: 20, swords: 100 });\n    t.verifica('faltam habitantes: junta exactamente os espadachins precisos',\n      r.escudoExtra === 26 && r.reg.some((x) => /junto 26 espadachins/.test(x)), r);\n  }\n  {\n    const r = decidir({ minimo: 86, quantos: 20, swords: 26 });\n    t.verifica('tem mesmo os que faltam: não guarda nenhum em casa (falhava por um)',\n      r.escudoExtra === 26, r);\n  }\n  {\n    const r = decidir({ minimo: 86, quantos: 5, swords: 10 });\n    t.verifica('nem com tudo chega: espera, e diz os habitantes',\n      r.reg.some((x) => /não chegam ao mínimo de 86 habitantes/.test(x)), r.reg);\n  }\n  {\n    const r = decidir({ minimo: 0, quantos: 5, swords: 0 });\n    t.verifica('sem mínimo aprendido: não mexe em nada', r.escudoExtra === 0, r);\n  }\n  t.fim();\n})().catch((e) => { console.error('O TESTE REBENTOU:', e); process.exit(2); });\n",
 "teste-encaixe-carga.js": "/* ENCAIXE — as composições enchem os barcos até cima.\n *\n * A capacidade saía da tabela base (10 e 26) e ignorava a pesquisa de porões\n * (16 e 32). Com 138 transportes rápidos davam-se 1380 lugares em vez de 2208:\n * as composições levavam menos 293 de tropa (visto em jogo, 13/09). O\n * enchimento REAL do módulo.\n *\n *   node ferramentas/teste-encaixe-carga.js maestro.user.js\n */\nconst S = require('./simulador');\nconst { vm, tira, igual } = S;\nconst SRC = S.ficheiroDoMaestro();\nconst t = S.verificador('ENCAIXE — CARGA');\n\n/* A cidade da imagem: 950 espadachins, 965 arqueiros, 481 hoplitas, 138\n * transportes rápidos. */\nconst TENHO = { sword: 950, archer: 965, hoplite: 481, small_transporter: 138 };\nconst GD = {\n  sword: { population: 1 }, archer: { population: 1 }, hoplite: { population: 1 },\n  small_transporter: { is_naval: true, capacity: 10 }, big_transporter: { is_naval: true, capacity: 26 },\n};\n\nfunction encher(carga, poroes, tenho) {\n  const ctx = {\n    gd: GD, tenho: tenho || TENHO, carga,\n    t: { researches: () => ({ attributes: poroes ? { berth: true } : {} }) },\n    seErroDeCodigo: () => {}, Number, Object, Math,\n  };\n  vm.createContext(ctx);\n  vm.runInContext(tira(SRC, '            try {\\n              /* OS PORÕES CONTAM.', '            } catch (e) { seErroDeCodigo(e, \\'Encaixe\\'); }\\n'), ctx);\n  return ctx.carga;\n}\nconst soma = (c) => Object.keys(c).filter((u) => !GD[u].is_naval)\n  .reduce((s, u) => s + (Number(c[u]) || 0) * (GD[u].population || 1), 0);\n\n(async () => {\n  {\n    const c = encher({ small_transporter: 138 }, true);\n    t.verifica('com porões: 138 transportes = 2208 lugares, cheios', soma(c) === 2208, { c, soma: soma(c) });\n    t.verifica('... e sobra hoplitas para os 293 lugares que faltavam',\n      c.sword === 950 && c.archer === 965 && c.hoplite === 293, c);\n  }\n  {\n    const c = encher({ small_transporter: 138 }, false);\n    t.verifica('sem porões: 1380 lugares (era isto que dava sempre)', soma(c) === 1380, soma(c));\n  }\n  {\n    const c = encher({ small_transporter: 138, big_transporter: 1 }, true);\n    t.verifica('com um barco grande: mais 32 lugares', soma(c) === 2240, soma(c));\n  }\n  {\n    const c = encher({ small_transporter: 400 }, true);\n    t.verifica('barcos a mais do que tropa: leva a tropa toda e não inventa',\n      soma(c) === 950 + 965 + 481, { c, soma: soma(c) });\n  }\n  {\n    const c = encher({}, true);\n    t.verifica('sem transportes: não leva tropa nenhuma', soma(c) === 0, c);\n  }\n  t.fim();\n})().catch((e) => { console.error('O TESTE REBENTOU:', e); process.exit(2); });\n",
 "teste-encaixe.js": "/* ENCAIXE — a leitura da visão geral, SEMPRE fresca.\n *\n * O encaixe pergunta a seguir a enviar: uma cópia de há 20 s não tem o comando\n * que acabou de sair. E uma leitura falhada deixa sempre a razão registada\n * (sai na linha [diagnóstico]).\n *\n *   node ferramentas/teste-encaixe.js maestro.user.js\n */\nconst S = require('./simulador');\nconst { AGORA_S, vm, tira, funcao, jogo, carregarNucleo, semAdministrador, correr, ligar, lista, ERRO, LIMITADO,\n  igual } = S;\nconst SRC = S.ficheiroDoMaestro();\n\nconst t = S.verificador('ENCAIXE');\n\nfunction encaixe(j) {\n  const ini = SRC.indexOf('MÓDULO: ENCAIXE DE COMANDOS');\n  const marcas = tira(SRC, '  let semAdmAte = 0;', \"  let ultimaRazaoVazio = '';\\n\", 'MÓDULO: ENCAIXE DE COMANDOS');\n  const txt = marcas + funcao(SRC, '  async function lerResposta(resposta) {', 'MÓDULO: ENCAIXE DE COMANDOS')\n    + funcao(SRC, \"  async function comandosDoServidor(townId) {\\n    if (semAdministrador())\", 'MÓDULO: ENCAIXE DE COMANDOS')\n    + '\\n({ ler: comandosDoServidor, razao: () => ultimaRazaoVazio })';\n  void ini;\n  const ctx = { mUw: j.win, window: j.win, uw: j.win, seErroDeCodigo: () => {}, console };\n  vm.createContext(ctx);\n  return vm.runInContext(txt, ctx);\n}\n\nconst CMDS = [\n  { id: 801, type: 'attack_land', own_command: true, started_at: AGORA_S - 5, origin_town_id: 111,\n    destination_town_id: 5555, arrival_at: AGORA_S + 3600, cancelable: true },\n  { id: 802, type: 'attack_land', own_command: true, return: true, started_at: AGORA_S - 900, origin_town_id: 5556,\n    destination_town_id: 111, arrival_at: AGORA_S + 60 },\n  { id: 803, type: 'support', own_command: true, started_at: AGORA_S - 30, origin_town_id: 222,\n    destination_town_id: 5557, arrival_at: AGORA_S + 1200, cancelable: false },\n];\n\n(async () => {\n  for (const [nome, corpo] of [['json.data.commands', { json: { data: { commands: CMDS } } }], ['json.commands', { json: { commands: CMDS } }]]) {\n    const j = jogo({ respostas: [{ corpo }] }); carregarNucleo(SRC, j);\n    const d = await encaixe(j).ler(111);\n    t.verifica(`${nome}: os comandos, sem a volta`, igual(d.map((x) => x.command_id), [801, 803]) && d[0].cancelavel === true, d);\n  }\n  {\n    const j = jogo({ respostas: [lista(CMDS.slice(1)), lista(CMDS)] }); carregarNucleo(SRC, j);\n    const outro = await j.win.__maestroVisaoGeral();\n    const d = await encaixe(j).ler(111);\n    t.verifica('com uma cópia recente sem o comando novo: vai ao servidor e encontra-o',\n      outro.ok && j.pedidosVG() === 2 && d.some((x) => x.command_id === 801), { pedidos: j.pedidosVG(), d });\n    const depois = await j.win.__maestroVisaoGeral();\n    t.verifica('... e a leitura dele passa a ser a cópia dos outros', depois.daCopia && depois.comandos.some((x) => x.id === 801));\n  }\n  {\n    const j = jogo({ respostas: [lista(CMDS)] }); carregarNucleo(SRC, j);\n    const e = encaixe(j); await e.ler(111); await e.ler(111); await e.ler(111);\n    t.verifica('três leituras seguidas depois de enviar → três pedidos (nada vem da cópia)', j.pedidosVG() === 3, j.pedidosVG());\n  }\n  for (const [nome, resp, re] of [['erro do jogo', ERRO, /^Ocorreu um erro\\.$/], ['lista vazia', lista([]), /veio sem comandos/],\n    ['429', LIMITADO, /recusar/], ['resposta sem lista', { corpo: { json: { data: { outra: 1 } } } }, /não traz a lista/]]) {\n    const j = jogo({ respostas: [resp] }); carregarNucleo(SRC, j);\n    const e = encaixe(j); const d = await e.ler(111);\n    t.verifica(`${nome}: lista vazia e a razão registada`, d.length === 0 && re.test(e.razao()), e.razao());\n  }\n  {\n    const j = jogo({ respostas: [{ corpo: { json: { error: 'Necessita do administrador para aceder às visões gerais' } } }] });\n    carregarNucleo(SRC, j);\n    const e = encaixe(j); await e.ler(111); const r1 = e.razao(); await e.ler(111);\n    t.verifica('o servidor diz que falta o Administrador: diz porquê e não volta a pedir', /falta o Administrador/.test(r1)\n      && j.pedidosVG() === 1, { r1, pedidos: j.pedidosVG() });\n  }\n  t.fim();\n})().catch((e) => { console.error('O TESTE REBENTOU:', e); process.exit(2); });\n",
 "teste-esquiva-margem.js": "/* ESQUIVA — a margem tem de chegar para a preparação.\n *\n * Eram 20 s entre a saída e o impacto. Mas entre o temporizador disparar e a\n * tropa sair passam-se segundos a actualizar contadores, carregar a ilha e\n * fazer os envios: numa cidade com três envios foram 36 s e a tropa saiu\n * DEPOIS do impacto (visto em jogo, 14/09, ataque às 11:17:58).\n *\n *   node ferramentas/teste-esquiva-margem.js maestro.user.js\n */\nconst S = require('./simulador');\nconst { vm, funcao } = S;\nconst SRC = S.ficheiroDoMaestro();\nconst t = S.verificador('ESQUIVA — MARGEM');\nconst ES = 'function makeEsquivaModule(opts)';\n\nfunction montar(guardado) {\n  const loja = guardado == null ? {} : { grepoEsquiva_preparo_v1: String(guardado) };\n  const ctx = {\n    armazem: { getItem: (k) => (k in loja ? loja[k] : null), setItem: (k, v) => { loja[k] = v; } },\n    seErroDeCodigo: () => {}, console, Number, Math,\n    PREPARO_KEY: 'grepoEsquiva_preparo_v1',\n  };\n  vm.createContext(ctx);\n  const api = vm.runInContext(funcao(SRC, '  function preparoConhecido() {', ES)\n    + funcao(SRC, '  function anotarPreparo(segundos) {', ES)\n    + '\\n({ ler: preparoConhecido, anotar: anotarPreparo })', ctx);\n  return { api, loja };\n}\n\n(async () => {\n  {\n    const m = montar(null);\n    t.verifica('sem histórico: não acrescenta margem nenhuma', m.api.ler() === 0);\n  }\n  {\n    const m = montar(null);\n    m.api.anotar(36);\n    t.verifica('uma esquiva que levou 36 s: passa a contar com 36', m.api.ler() === 36, m.api.ler());\n  }\n  {\n    const m = montar(36);\n    m.api.anotar(50);\n    t.verifica('uma mais lenta: sobe já para 50', m.api.ler() === 50, m.api.ler());\n  }\n  {\n    const m = montar(50);\n    m.api.anotar(10);\n    t.verifica('uma rápida: desce devagar, não confia num arranque bom', m.api.ler() > 30 && m.api.ler() < 50, m.api.ler());\n    for (let i = 0; i < 20; i++) m.api.anotar(10);\n    t.verifica('... mas ao fim de muitas rápidas aproxima-se delas', m.api.ler() <= 12, m.api.ler());\n  }\n  {\n    const m = montar(null);\n    m.api.anotar(600);\n    t.verifica('um caso absurdo fica travado nos 3 min', m.api.ler() === 180, m.api.ler());\n  }\n  {\n    const m = montar(null);\n    m.api.anotar(-5);\n    t.verifica('valor sem sentido não estraga nada', m.api.ler() === 0, m.api.ler());\n  }\n  t.fim();\n})().catch((e) => { console.error('O TESTE REBENTOU:', e); process.exit(2); });\n",
 "teste-fechar-ilha-mapa.js": "/* FECHAR ILHA — ler a ilha no mapa.\n *\n * A grelha do mapa é de 20: com 10 o servidor devolve outro pedaço e a ilha\n * vinha sem cidade nenhuma — \"20 lugares livres\" numa ilha com 22 cidades\n * (visto em jogo, 12/09, ilha 381:470). E uma leitura falhada não pode contar\n * como ilha vazia. O `estadoDaIlha` REAL.\n *\n *   node ferramentas/teste-fechar-ilha-mapa.js maestro.user.js\n */\nconst S = require('./simulador');\nconst { vm, funcao, igual } = S;\nconst SRC = S.ficheiroDoMaestro();\nconst t = S.verificador('FECHAR ILHA — MAPA');\nconst FI = 'function makeFecharIlhaModule(opts)';\n\n/* A ilha 381:470 como o jogo a devolveu: cidades nos lugares 0..20 e 23,\n * mais aldeias sem lugar (nr nulo). Só responde à grelha certa. */\nfunction montar(grelhaBoa, falha) {\n  const pedidos = [];\n  const towns = {};\n  [...Array(21).keys()].concat([23]).forEach((nr, i) => {\n    towns['t' + i] = { x: 381, y: 470, nr, name: 'Cidade ' + nr, player_id: 100 + i, alliance_id: 7 };\n  });\n  for (let i = 0; i < 6; i++) towns['f' + i] = { x: 381, y: 470, nr: null, name: 'Aldeia' };\n  towns['outra'] = { x: 382, y: 470, nr: 3, name: 'De outra ilha' };\n  const mUw = {\n    location: { origin: 'https://pt125.grepolis.com' }, Game: { csrfToken: 'TOK' },\n    fetch: async (url) => {\n      pedidos.push(String(url));\n      if (falha) throw new Error('rede em baixo');\n      const j = JSON.parse(decodeURIComponent((String(url).match(/json=([^&]+)/) || [])[1]));\n      const c = (j.chunks || [])[0] || {};\n      /* O servidor só devolve as cidades quando o bloco é o certo. */\n      const certo = c.x === Math.floor(381 / grelhaBoa) && c.y === Math.floor(470 / grelhaBoa);\n      const corpo = JSON.stringify({ json: { data: { 0: { chunk: c, towns: certo ? towns : {} } } } });\n      return { status: 200, text: async () => corpo, json: async () => JSON.parse(corpo) };\n    },\n  };\n  const ctx = { mUw, LUGARES: 20, seErroDeCodigo: () => {}, console, window: {} };\n  vm.createContext(ctx);\n  const f = vm.runInContext(funcao(SRC, '  async function estadoDaIlha(ix, iy, townIdBase) {', FI) + '\\nestadoDaIlha', ctx);\n  return { f, pedidos };\n}\n\n(async () => {\n  {\n    const m = montar(20, false);\n    const r = await m.f(381, 470, 111);\n    t.verifica('pede o bloco da grelha de 20', /%22x%22%3A19/.test(m.pedidos[0]) || /\"x\":19/.test(decodeURIComponent(m.pedidos[0])), m.pedidos[0].slice(0, 120));\n    t.verifica('vê as 22 cidades da ilha (e ignora as de outra ilha)', r.ocupados === 22, r.ocupados);\n    t.verifica('a ilha tem 24 lugares, porque há cidade no 23', r.total === 24, r.total);\n    t.verifica('livres: só o 21 e o 22', igual(r.livres, [21, 22]), r.livres);\n    t.verifica('e diz que leu', r.lido === true);\n  }\n  {\n    const m = montar(10, false);   // se o módulo pedisse com 10, não via nada\n    const r = await m.f(381, 470, 111);\n    t.verifica('com a grelha errada não viria nada — é o erro que isto apanha',\n      r.ocupados === 0 && r.livres.length === 20, { o: r.ocupados, l: r.livres.length });\n  }\n  {\n    const m = montar(20, true);\n    const r = await m.f(381, 470, 111);\n    t.verifica('pedido falhado: diz que NÃO leu (não é ilha vazia)', r.lido === false, r);\n  }\n  t.fim();\n})().catch((e) => { console.error('O TESTE REBENTOU:', e); process.exit(2); });\n",
 "teste-fechar-ilha-vagas.js": "/* FECHAR ILHA — as vagas quem as diz é o jogo.\n *\n * O mapa traz o que a conta viu e não esquece cidades que já lá não estão: na\n * ilha 381:470 dava 22 cidades quando o jogo dizia 9 e 11 vagas (12/09). O\n * `forceUpdate` da colonização devolve `uninhabited_place_count` e propõe um\n * lugar LIVRE, diferente de cada vez. O código REAL.\n *\n *   node ferramentas/teste-fechar-ilha-vagas.js maestro.user.js\n */\nconst S = require('./simulador');\nconst { vm, funcao } = S;\nconst SRC = S.ficheiroDoMaestro();\nconst t = S.verificador('FECHAR ILHA — VAGAS');\nconst FI = 'function makeFecharIlhaModule(opts)';\n\n/* A ilha 381:470: 9 cidades, 11 vagas. O jogo propõe os lugares por esta\n * ordem, como fez em jogo (14, 7, 12…). */\nfunction montar(propostas, formato) {\n  const pedidos = [];\n  const mUw = {\n    location: { origin: 'https://pt126.grepolis.com' },\n    Game: { csrfToken: 'TOK', player_id: 2379469 },\n    fetch: async (url, op) => {\n      pedidos.push(JSON.parse(decodeURIComponent(String(op.body).replace('json=', ''))));\n      const lugar = propostas[Math.min(pedidos.length - 1, propostas.length - 1)];\n      const dados = { enough_culture_points: true, target_x: 381, target_y: 470,\n        target_number_on_island: lugar,\n        island_info: { island_id: 55319, uninhabited_place_count: 11,\n          town_list: Array.from({ length: 9 }, (_, i) => ({ id: i, name: 'C' + i })) } };\n      /* O jogo devolve isto de duas maneiras: em models, ou dentro das\n       * notificações, em texto escapado. */\n      /* As três formas vistas em jogo (12/09). */\n      const corpo = formato === 'notificacao'\n        ? JSON.stringify({ json: { t_token: 1, notifications: [{ type: 'backbone',\n          param_str: JSON.stringify({ Colonization: dados }) }] } })\n        : formato === 'notificacao_data'\n          ? JSON.stringify({ json: { t_token: 1, notifications: [\n            { type: 'outra', param_str: '{}' },\n            { type: 'backbone', param_str: JSON.stringify({ Colonization: { data: dados } }) }] } })\n          : JSON.stringify({ json: { models: { Colonization: { data: dados } } } });\n      return { status: 200, text: async () => corpo, json: async () => JSON.parse(corpo) };\n    },\n  };\n  const ctx = { mUw, LUGARES: 20, seErroDeCodigo: () => {}, console, setTimeout, window: {} };\n  vm.createContext(ctx);\n  const txt = funcao(SRC, '  async function vagasDaIlha(townId, x, y, lugarSugerido) {', FI)\n    + funcao(SRC, '  async function lugarLivrePorUsar(townId, x, y, jaUsados) {', FI)\n    + '\\n({ vagas: vagasDaIlha, livre: lugarLivrePorUsar })';\n  return { api: vm.runInContext(txt, ctx), pedidos };\n}\n\n(async () => {\n  for (const f of ['models', 'notificacao', 'notificacao_data']) {\n    const m = montar([14], f);\n    const v = await m.api.vagas(111, 381, 470);\n    t.verifica(`resposta em ${f}: 11 vagas, 9 cidades, lugar 14`, v.ok && v.vagas === 11\n      && v.cidades === 9 && v.lugar === 14, v);\n  }\n  {\n    const m = montar([14], 'models');\n    const r = await m.api.livre(111, 381, 470, new Set());\n    t.verifica('nenhum lugar tomado: fica com o que o jogo deu', r.ok && r.lugar === 14\n      && m.pedidos.length === 1, { r, p: m.pedidos.length });\n  }\n  {\n    const m = montar([14, 7, 12], 'models');\n    const r = await m.api.livre(111, 381, 470, new Set([14, 7]));\n    t.verifica('lugares já usados por outras contas: pede outro até dar', r.ok && r.lugar === 12\n      && m.pedidos.length === 3, { r, p: m.pedidos.length });\n  }\n  {\n    const m = montar([14], 'models');\n    const r = await m.api.livre(111, 381, 470, new Set([14]));\n    t.verifica('o jogo insiste no mesmo: desiste e diz quais viu', !r.ok\n      && /só me propôs lugares que outras contas/.test(r.msg), r);\n  }\n  {\n    /* NUNCA se sugere um número: sugerir um ocupado dá \"posição não válida\"\n     * e a conta desistia da ilha (14/09). */\n    const m = montar([14, 7, 12], 'models');\n    await m.api.livre(111, 381, 470, new Set([14, 7]));\n    t.verifica('as tentativas seguintes não sugerem lugar nenhum',\n      m.pedidos.every((p) => !('target_number_on_island' in (p.arguments || {}))),\n      m.pedidos.map((p) => p.arguments));\n  }\n  {\n    const m = montar([14], 'models');\n    const r = await m.api.vagas(111, 381, 470, 9);\n    t.verifica('pode sugerir-se um lugar ao jogo', m.pedidos[0].arguments.target_number_on_island === 9\n      && r.ok, m.pedidos[0].arguments);\n  }\n  {\n    const ctx = { mUw: { location: { origin: 'https://x' }, Game: {},\n      fetch: async () => ({ text: async () => '{\"json\":{\"t_token\":1}}' }) },\n      LUGARES: 20, seErroDeCodigo: () => {}, console, setTimeout, window: {} };\n    vm.createContext(ctx);\n    const f = vm.runInContext(funcao(SRC, '  async function vagasDaIlha(townId, x, y, lugarSugerido) {', FI)\n      + '\\nvagasDaIlha', ctx);\n    const v = await f(111, 381, 470);\n    t.verifica('resposta sem a ficha da ilha: diz que não deu (não inventa vagas)', !v.ok, v);\n  }\n  t.fim();\n})().catch((e) => { console.error('O TESTE REBENTOU:', e); process.exit(2); });\n",
 "teste-fechar-ilha.js": "/* FECHAR ILHA — cada conta escreve só a sua chave.\n *\n * Vinte contas à partida a ler o plano inteiro, mexer na sua parte e gravá-lo\n * inteiro: ganhava a última a gravar. O que cada conta fez (enviei, falhei,\n * desisti, mudei de lugar) vai para a chave dela, e quem lê o plano junta\n * tudo. O código REAL do módulo, com um Firebase de mentira partilhado por\n * várias contas (cada uma com o seu módulo).\n *\n *   node ferramentas/teste-fechar-ilha.js maestro.user.js\n */\nconst S = require('./simulador');\nconst { vm, tira } = S;\nconst SRC = S.ficheiroDoMaestro();\nconst t = S.verificador('FECHAR ILHA');\n\n/* Um Firebase de mentira: caminhos com \"/\", cópias à entrada e à saída. */\nfunction firebase() {\n  const raiz = {};\n  const partes = (p) => String(p).split('/').filter(Boolean);\n  const copia = (v) => (v === undefined ? null : JSON.parse(JSON.stringify(v)));\n  return {\n    raiz,\n    url: () => 'https://falso',\n    ler: async (p) => { let n = raiz; for (const k of partes(p)) { if (!n || typeof n !== 'object') return null; n = n[k]; } return copia(n); },\n    escrever: async (p, v) => {\n      const ks = partes(p); let n = raiz;\n      for (const k of ks.slice(0, -1)) { if (!n[k] || typeof n[k] !== 'object') n[k] = {}; n = n[k]; }\n      n[ks[ks.length - 1]] = copia(v); return { ok: true };\n    },\n  };\n}\n\n/* O troço do módulo que lê e grava o plano, para uma conta. */\nfunction conta(fb, nome) {\n  const txt = tira(SRC, '  /* ---------------------- o plano, no Firebase -------------------------- */',\n    '  /* ---------------------- leitura da ilha ------------------------------- */')\n    + '\\n' + tira(SRC, '  const chaveSegura = (ch) =>', ';\\n')\n    + '\\n({ lerPlano, gravarPlano, registarMeu: (p, campos) => registarMeu(p, eu, campos), lerFila, planoActivo })';\n  const ctx = { mWorld: 'pt125', eu: nome, janela: () => ({ __maestroFb: fb }), seErroDeCodigo: () => {}, console };\n  vm.createContext(ctx);\n  return vm.runInContext(txt, ctx);\n}\n\nconst PLANO = { chave: '365:460', x: 365, y: 460, estado: 'lancar', criadoPor: 'Dono',\n  atribuicoes: { A: 1, B: 2, 'Jo.ao': 3, Dono: 4 }, enviados: { Dono: 100 } };\nasync function montar() {\n  const fb = firebase();\n  await fb.escrever('fecharIlhaFila/pt125', { planos: [JSON.parse(JSON.stringify(PLANO))], parada: false });\n  return fb;\n}\n\n(async () => {\n  {\n    /* A MANEIRA ANTIGA, com o código de agora: ler, mexer, gravar tudo. */\n    const fb = await montar();\n    const a = conta(fb, 'A'); const dono = conta(fb, 'Dono');\n    const pa = await a.lerPlano(); const pd = await dono.lerPlano();\n    pa.enviados.A = 200; await a.gravarPlano(pa);\n    pd.estado = 'feito'; await dono.gravarPlano(pd);\n    const fim = (await fb.ler('fecharIlhaFila/pt125')).planos[0];\n    t.verifica('a maneira antiga perde o envio de uma conta (é por isto que mudou)', !fim.enviados.A, fim.enviados);\n  }\n  {\n    const fb = await montar();\n    const a = conta(fb, 'A'); const dono = conta(fb, 'Dono'); const outra = conta(fb, 'B');\n    const pa = await a.lerPlano(); const pd = await dono.lerPlano();\n    await a.registarMeu(pa, { enviado: 200, lugar: 1 });\n    pd.estado = 'feito'; await dono.gravarPlano(pd);\n    const visto = await outra.lerPlano() || (await outra.lerFila()).planos[0];\n    const fila = (await fb.ler('fecharIlhaFila/pt125')).planos[0];\n    t.verifica('agora: o envio da conta fica, e o estado do dono também', fila.estado === 'feito'\n      && (await fb.ler('fecharIlhaEnvios/pt125/365_460/A')).enviado === 200, { fila, visto });\n  }\n  {\n    /* Ordem inversa: o dono grava primeiro, a conta depois. */\n    const fb = await montar();\n    const a = conta(fb, 'A'); const dono = conta(fb, 'Dono'); const outra = conta(fb, 'B');\n    const pa = await a.lerPlano(); const pd = await dono.lerPlano();\n    pd.estado = 'preparar'; pd.marca = 'do dono'; await dono.gravarPlano(pd);\n    await a.registarMeu(pa, { falhou: 'sem vaga' });\n    const fila = (await fb.ler('fecharIlhaFila/pt125')).planos[0];\n    t.verifica('a conta já não desfaz o que o dono gravou', fila.marca === 'do dono' && fila.estado === 'preparar', fila);\n    const p = await outra.lerPlano();\n    t.verifica('... e quem lê vê a falha da conta', p && p.falhados && p.falhados.A === 'sem vaga', p && p.falhados);\n  }\n  {\n    const fb = await montar();\n    const b = conta(fb, 'B'); const dono = conta(fb, 'Dono');\n    await b.registarMeu(await b.lerPlano(), { falhou: '4 tentativas', lugar: 7 });\n    const pd = await dono.lerPlano();\n    t.verifica('o lugar que a conta usou entra no plano de quem lê', pd.atribuicoes.B === 7, pd.atribuicoes);\n    pd.atribuicoes.C = pd.atribuicoes.B; delete pd.atribuicoes.B; await dono.gravarPlano(pd);\n    const p2 = await dono.lerPlano();\n    t.verifica('se o dono passar o lugar a outra conta, ganha o dono', p2.atribuicoes.B === undefined && p2.atribuicoes.C === 7, p2.atribuicoes);\n  }\n  {\n    const fb = await montar();\n    const a = conta(fb, 'A');\n    const p = await a.lerPlano();\n    await a.registarMeu(p, { tentativas: 2 });\n    await a.registarMeu(p, { enviado: 300 });\n    const rec = await fb.ler('fecharIlhaEnvios/pt125/365_460/A');\n    t.verifica('o registo da conta junta o que já lá estava (tentativas e envio)', rec.tentativas === 2 && rec.enviado === 300, rec);\n  }\n  {\n    const fb = await montar();\n    const j = conta(fb, 'Jo.ao'); const dono = conta(fb, 'Dono');\n    await j.registarMeu(await j.lerPlano(), { enviado: 400 });\n    const pd = await dono.lerPlano();\n    t.verifica('nome com ponto: a chave fica segura e o envio vai para o nome certo', pd.enviados['Jo.ao'] === 400\n      && (await fb.ler('fecharIlhaEnvios/pt125/365_460/Jo_ao')).conta === 'Jo.ao', pd.enviados);\n  }\n  /* A FILA LIMPA TEM DE FICAR LIMPA. */\n  {\n    const fb = firebase();\n    /* Como o Firebase faz: uma lista vazia não se guarda. */\n    const escreverReal = fb.escrever;\n    fb.escrever = async (p, v) => {\n      const c = JSON.parse(JSON.stringify(v || {}));\n      if (c && Array.isArray(c.planos) && !c.planos.length) delete c.planos;\n      return escreverReal(p, c);\n    };\n    await fb.escrever('fecharIlha/pt125', { chave: '100:100', atribuicoes: { A: 0 }, estado: 'preparar' });\n    const c = conta(fb, 'A');\n    const antes = await c.lerFila();\n    t.verifica('sem fila nenhuma: aproveita o plano do formato antigo', antes.planos.length === 1, antes);\n    await fb.escrever('fecharIlhaFila/pt125', { planos: [], parada: false });\n    const dep = await c.lerFila();\n    t.verifica('fila gravada vazia: fica vazia (não ressuscita o plano antigo)', dep.planos.length === 0, dep);\n  }\n  /* UMA DESISTÊNCIA POR TENTATIVAS CADUCA. */\n  {\n    const fb = await montar();\n    const a = conta(fb, 'A');\n    const p = await a.lerPlano();\n    await a.registarMeu(p, { falhou: '4 tentativas sem sucesso (posição não válida)', tentativas: 4 });\n    const p2 = await a.lerPlano();\n    t.verifica('a falha fica registada', p2.falhados.A === '4 tentativas sem sucesso (posição não válida)', p2.falhados);\n    await a.registarMeu(p2, { falhou: '', tentativas: 0 });\n    const p3 = await a.lerPlano();\n    t.verifica('uma falha vazia apaga a desistência', !p3.falhados || !p3.falhados.A, p3.falhados);\n    t.verifica('... e o registo da conta continua lá para o resto',\n      !!(await fb.ler('fecharIlhaEnvios/pt125/365_460/A')), await fb.ler('fecharIlhaEnvios/pt125/365_460/A'));\n  }\n  t.fim();\n})().catch((e) => { console.error('O TESTE REBENTOU:', e); process.exit(2); });\n",
 "teste-fundacao-mapa.js": "/* FUNDAÇÃO — procurar ilhas sem levar 429.\n *\n * A procura pedia um bloco do mapa de cada vez, em rajada: ao guardar a\n * configuração saíram dezenas de pedidos seguidos, o servidor respondeu 429 a\n * quase todos, e cada 429 pára o maestro dois minutos (visto em jogo, 14/09:\n * 40 erros em segundos). O `get_chunks` aceita uma lista. O `pedirBlocos` REAL.\n *\n *   node ferramentas/teste-fundacao-mapa.js maestro.user.js\n */\nconst S = require('./simulador');\nconst { vm, funcao } = S;\nconst SRC = S.ficheiroDoMaestro();\nconst t = S.verificador('FUNDAÇÃO — MAPA');\nconst FU = 'function makeFundacaoModule(opts)';\n\nfunction montar(travadoAoFim) {\n  const pedidos = [];\n  let travado = false;\n  const ctx = {\n    mUw: {\n      location: { origin: 'https://pt125.grepolis.com' }, Game: { csrfToken: 'TOK' },\n      ITowns: { towns: { 111: {} } },\n      fetch: async (url) => {\n        const j = JSON.parse(decodeURIComponent((String(url).match(/json=([^&]+)/) || [])[1]));\n        pedidos.push(j.chunks.length);\n        if (travadoAoFim && pedidos.length >= travadoAoFim) travado = true;\n        const data = {};\n        j.chunks.forEach((c, i) => { data[i] = { chunk: c, islands: [{ x: c.x * 20, y: c.y * 20, id: 1 }] }; });\n        const corpo = JSON.stringify({ json: { data } });\n        return { status: 200, text: async () => corpo, json: async () => JSON.parse(corpo) };\n      },\n    },\n    window: { __maestroServidorTravado: () => travado },\n    lerResposta: async (r) => JSON.parse(await r.text()),\n    seErroDeCodigo: () => {}, console, setTimeout,\n  };\n  vm.createContext(ctx);\n  const f = vm.runInContext(funcao(SRC, '  function servidorTravadoAgora() {', FU)\n    + funcao(SRC, '  async function pedirBlocos(lista, townIdBase) {', FU) + '\\npedirBlocos', ctx);\n  return { f, pedidos };\n}\n\nconst blocos = (n) => Array.from({ length: n }, (_, i) => ({ x: i, y: i }));\n\n(async () => {\n  {\n    const m = montar(0);\n    const r = await m.f(blocos(25), 111);\n    t.verifica('25 blocos → 5 pedidos de 6, não 25', m.pedidos.length === 5, m.pedidos);\n    t.verifica('... e devolve os 25 blocos', r.length === 25, r.length);\n  }\n  {\n    const m = montar(0);\n    await m.f(blocos(4), 111);\n    t.verifica('poucos blocos: um pedido só', m.pedidos.length === 1 && m.pedidos[0] === 4, m.pedidos);\n  }\n  {\n    /* O servidor começa a recusar ao segundo pedido. */\n    const m = montar(2);\n    const r = await m.f(blocos(30), 111);\n    t.verifica('servidor a recusar: pára em vez de insistir', m.pedidos.length === 2, m.pedidos.length);\n    t.verifica('... e devolve o que já tinha', r.length === 12, r.length);\n  }\n  {\n    const m = montar(0);\n    const r = await m.f([], 111);\n    t.verifica('nada a pedir: nenhum pedido', m.pedidos.length === 0 && r.length === 0);\n  }\n  /* A PROCURA TEM DE PODER IR MAIS LONGE. */\n  {\n    const pedidos = [];\n    const ctx = {\n      mUw: { location: { origin: 'https://x' }, Game: { csrfToken: 'T' }, ITowns: { towns: { 111: {} } },\n        fetch: async (url) => {\n          const j = JSON.parse(decodeURIComponent((String(url).match(/json=([^&]+)/) || [])[1]));\n          j.chunks.forEach((c) => pedidos.push(`${c.x}:${c.y}`));\n          const data = {};\n          /* Só há ilhas a partir do anel 5 — perto do centro está tudo tomado. */\n          j.chunks.forEach((c, i) => {\n            const anel = Math.max(Math.abs(c.x - 10), Math.abs(c.y - 10));\n            data[i] = { islands: anel >= 5 ? [{ x: c.x * 20, y: c.y * 20, id: anel }] : [] };\n          });\n          const corpo = JSON.stringify({ json: { data } });\n          return { status: 200, text: async () => corpo, json: async () => JSON.parse(corpo) };\n        } },\n      window: { __maestroServidorTravado: () => false },\n      lerResposta: async (r) => JSON.parse(await r.text()),\n      CHUNK: 20, oceanoDe: () => 55, seErroDeCodigo: () => {}, console, setTimeout,\n    };\n    vm.createContext(ctx);\n    const f = vm.runInContext(funcao(SRC, '  function servidorTravadoAgora() {', FU)\n      + funcao(SRC, '  async function pedirBlocos(lista, townIdBase) {', FU)\n      + funcao(SRC, '  async function ilhasPertoDe(centro, oceanos, townIdBase, minimo, anelDe, anelAte) {', FU)\n      + '\\nilhasPertoDe', ctx);\n    const centro = { x: 200, y: 200 };\n    const perto = await f(centro, [], 111, 24, 1, 4);\n    t.verifica('até ao anel 4 não há nada (é o caso de 14/09)', perto.length === 0, perto.length);\n    const longe = await f(centro, [], 111, 24, 5, 8);\n    t.verifica('do anel 5 ao 8 já aparecem ilhas', longe.length > 0, longe.length);\n    t.verifica('... e não se repetem blocos dentro do mesmo degrau',\n      new Set(pedidos).size === pedidos.length, { pedidos: pedidos.length, únicos: new Set(pedidos).size });\n  }\n  t.fim();\n})().catch((e) => { console.error('O TESTE REBENTOU:', e); process.exit(2); });\n",
 "teste-leitores.js": "/* FEITIÇOS, DEUSES, REFORÇO — a visão geral pelo leitor do núcleo.\n *\n * O que tem de ser: a lista certa das duas chaves; \"não consegui ler\" nunca é\n * \"não há nada\" (o reforço não traz tropa às cegas, o farm não ataca sem saber\n * o favor a caminho); sem Administrador não se pede; os três juntos fazem um\n * pedido só.\n *\n *   node ferramentas/teste-leitores.js maestro.user.js\n */\nconst S = require('./simulador');\nconst { AGORA_S, vm, tira, funcao, jogo, carregarNucleo, semAdministrador, correr, ligar, lista, ERRO, LIMITADO,\n  igual } = S;\nconst SRC = S.ficheiroDoMaestro();\n\nconst t = S.verificador('FEITIÇOS, DEUSES, REFORÇO');\n\nconst COMANDOS = [\n  { id: 1, type: 'attack', origin_town_id: 900, origin_town_name: 'Inimiga', destination_town_id: 111,\n    destination_town_name: 'A', arrival_at: AGORA_S + 3600 },\n  { id: 2, type: 'attack', origin_town_id: 901, destination_town_id: 222, arrival_at: AGORA_S + 7200 },\n  { id: 3, type: 'attack', return: true, origin_town_id: 902, destination_town_id: 111, arrival_at: AGORA_S + 60 },\n  { id: 4, type: 'attack', origin_town_id: 333, destination_town_id: 111, arrival_at: AGORA_S + 100 },\n  { id: 5, type: 'support', origin_town_id: 903, destination_town_id: 111, arrival_at: AGORA_S + 50 },\n  { id: 6, type: 'attack', origin_town_id: 904, destination_town_id: 555, arrival_at: AGORA_S + 50 },\n  { id: 7, type: 'attack', origin_town_id: 111, destination_town_id: 700, godsent: 10, arrival_at: AGORA_S + 900 },\n  { id: 8, type: 'attack', origin_town_id: 222, destination_town_id: 701, godsent: 4, cmd_return: true, arrival_at: AGORA_S + 900 },\n  { id: 9, type: 'attack', origin_town_id: 950, destination_town_id: 702, godsent: 20, arrival_at: AGORA_S + 900 },\n];\nconst MOVIMENTOS = {\n  m1: { attributes: { id: 50, type: 'attack', target_town_id: 222, home_town_id: 905, town_name_origin: 'SóModelo',\n    town_name_destination: 'B', arrival_at: AGORA_S + 500 } },\n  m2: { attributes: { id: 51, type: 'attack', target_town_id: 111, home_town_id: 900, town_name_origin: 'Inimiga',\n    town_name_destination: 'A', arrival_at: AGORA_S + 3600 } },\n};\n\nasync function feiticos(j) {\n  const txt = funcao(SRC, '  async function ataquesContraMim() {\\n    /* SEM REPETIDOS');\n  const ctx = { mUw: j.win, window: j.win, seErroDeCodigo: () => {},\n    armazem: { getItem: (k) => (k === 'grepoEsquiva_cidadesGrupo_v1' ? JSON.stringify({ ids: [333] }) : null) } };\n  vm.createContext(ctx);\n  const f = vm.runInContext(\"let razaoVisaoGeral = '';\\n\" + txt + '\\n({ f: ataquesContraMim, razao: () => razaoVisaoGeral })', ctx);\n  return { lista: await f.f(), razao: f.razao() };\n}\n\nasync function reforco(j, passagens) {\n  const ctx = { window: j.win, localStorage: j.localStorage, seErroDeCodigo: () => {}, console };\n  vm.createContext(ctx);\n  const mod = vm.runInContext(S.fabrica(SRC, 'makeReforcoModule') + '\\nmakeReforcoModule({ intervaloMin: 2 })', ctx);\n  const reg = { ecra: [], rotina: [] };\n  const c = { uw: j.win, log: (m) => reg.ecra.push(m), logRotina: (m) => reg.rotina.push(m),\n    sleep: async () => {}, rand: () => 0, getMyTowns: () => [{ id: 111 }, { id: 222 }] };\n  for (let i = 0; i < (passagens || 1); i++) await mod.run(c);\n  return reg;\n}\nconst reforcoLigado = (j) => {\n  j.localStorage.setItem('grepoReforco_cfg_v1', JSON.stringify({ ativo: true }));\n  j.localStorage.setItem('grepoReforco_envios_v1', JSON.stringify({\n    k1: { origem: 111, destino: 222, impacto: AGORA_S - 600, carga: { sword: 100 } } }));\n};\nconst BLOCO = { u1: { attributes: { id: 4242, home_town_id: 111, current_town_id: 222, sword: 100 } } };\nconst sendBacks = (j) => j.pedidos.filter((u) => /send_back/.test(u)).length;\n\nasync function deuses(j) {\n  const chamadas = { emCasa: 0 };\n  const ctx = { mUw: j.win, window: j.win, localStorage: j.localStorage, seErroDeCodigo: () => {},\n    favorPorDeus: () => ({ zeus: 10 }), deusDa: (id) => ({ 111: 'zeus', 222: 'zeus' }[id] || null),\n    pedidoDe: () => null, NOMES: { zeus: 'Zeus' }, chavePorPerfil: (k) => k,\n    enviadosEmCasa: () => { chamadas.emCasa++; return 0; },\n    escudoDisponivel: () => 0, alvosNaIlha: async () => [], proximoAlvo: () => null,\n    enviarAtaque: async () => ({ ok: true }), ilhaDa: () => ({ x: 1, y: 1 }),\n    minimoAprendido: () => 0, anotarMinimo: () => {}, recusaNormal: () => false, firebaseUrl: () => '' };\n  vm.createContext(ctx);\n  const f = vm.runInContext('let farmFalhasVisao = 0;\\n' + funcao(SRC, '  async function farmarFavor(ctx, c, towns) {')\n    + '\\nfarmarFavor', ctx);\n  const reg = { ecra: [], rotina: [] };\n  await f({ log: (m) => reg.ecra.push(m), logRotina: (m) => reg.rotina.push(m),\n    getMyTowns: () => [{ id: 111 }, { id: 222 }], sleep: async () => {}, rand: () => 0 },\n  { multis: ['multi1'], cidadesFarm: { 111: true }, favorParaAtacar: 100, favorPorEnviado: 5 }, [{ id: 111, name: 'A' }]);\n  return { reg, chamadas };\n}\n\n(async () => {\n  t.secao('FEITIÇOS — lista do painel');\n  for (const [nome, resp] of [['json.data.commands', lista(COMANDOS)], ['json.commands', { corpo: { json: { commands: COMANDOS } } }]]) {\n    const j = jogo({ respostas: [resp], movimentos: MOVIMENTOS }); carregarNucleo(SRC, j);\n    const r = await feiticos(j);\n    t.verifica(`${nome}: 3 ataques contra mim, sem repetidos nem os do meu grupo`,\n      igual(r.lista.map((x) => x.cid), [50, 51, 2]) && r.razao === '', r);\n  }\n  {\n    const j = jogo({ respostas: [ERRO], movimentos: MOVIMENTOS }); carregarNucleo(SRC, j);\n    const r = await feiticos(j);\n    t.verifica('leitura falhada: ficam os dos modelos, e a razão para o painel', r.lista.length === 2\n      && r.razao === 'Ocorreu um erro.', r);\n  }\n  {\n    const j = jogo({ respostas: [lista(COMANDOS)], movimentos: MOVIMENTOS, semAdm: true }); carregarNucleo(SRC, j);\n    const r = await feiticos(j);\n    t.verifica('sem Administrador: nenhum pedido, ficam os modelos', j.pedidosVG() === 0 && r.lista.length === 2\n      && r.razao === 'sem Administrador', r);\n  }\n\n  t.secao('REFORÇO');\n  {\n    const j = jogo({ respostas: [lista(COMANDOS)], units: BLOCO }); carregarNucleo(SRC, j); reforcoLigado(j);\n    const r = await reforco(j);\n    t.verifica('há outro ataque à cidade: a tropa fica', sendBacks(j) === 0\n      && r.rotina.some((m) => /a tropa fica em 222/.test(m)), r);\n  }\n  {\n    const j = jogo({ respostas: [lista(COMANDOS.filter((x) => x.destination_town_id !== 222))], units: BLOCO });\n    carregarNucleo(SRC, j); reforcoLigado(j);\n    const r = await reforco(j);\n    t.verifica('acabaram os ataques: traz a tropa de volta', sendBacks(j) === 1\n      && r.ecra.some((m) => /acabaram os ataques/.test(m)), r);\n    t.verifica('... e o envio de volta esquece a cópia da visão geral',\n      j.win.__maestroVisaoGeralEstado().copia === 'nenhuma', j.win.__maestroVisaoGeralEstado());\n  }\n  {\n    const j = jogo({ respostas: [ERRO], units: BLOCO }); carregarNucleo(SRC, j); reforcoLigado(j);\n    const r = await reforco(j, 3);\n    t.verifica('leitura falhada: não traz nada', sendBacks(j) === 0, r);\n    t.verifica('... avisa no ecrã uma vez, com a razão', r.ecra.length === 1\n      && /não consegui ler a visão geral \\(Ocorreu um erro\\.\\)/.test(r.ecra[0]), r.ecra);\n    t.verifica('... as repetições vão para a rotina', r.rotina.filter((m) => /não consegui ler/.test(m)).length === 2, r.rotina);\n    t.verifica('... e o registo do envio fica', !!JSON.parse(j.localStorage.getItem('grepoReforco_envios_v1')).k1);\n  }\n  {\n    const j = jogo({ respostas: [lista(COMANDOS)], units: BLOCO, semAdm: true }); carregarNucleo(SRC, j); reforcoLigado(j);\n    const r = await reforco(j);\n    t.verifica('sem Administrador: nenhum pedido, não traz nada, diz porquê', j.pedidosVG() === 0 && sendBacks(j) === 0\n      && /sem Administrador/.test(r.ecra[0] || ''), r);\n  }\n\n  t.secao('DEUSES — favor que vem a caminho');\n  {\n    const j = jogo({ respostas: [lista(COMANDOS)] }); carregarNucleo(SRC, j);\n    const r = await deuses(j);\n    t.verifica('conta só os enviados que vão (Zeus +50) e segue para os ataques',\n      r.reg.rotina.includes('Farm: já vem a caminho Zeus +50.') && r.chamadas.emCasa === 1, r);\n  }\n  {\n    const j = jogo({ respostas: [ERRO] }); carregarNucleo(SRC, j);\n    const r = await deuses(j);\n    t.verifica('leitura falhada: não ataca, e diz porquê', r.chamadas.emCasa === 0\n      && /não consegui ler a visão geral \\(Ocorreu um erro\\.\\)/.test(r.reg.ecra[0] || ''), r);\n  }\n  {\n    const j = jogo({ respostas: [lista(COMANDOS)], semAdm: true }); carregarNucleo(SRC, j);\n    const r = await deuses(j);\n    t.verifica('sem Administrador: fica como sempre (ataca), sem pedido', r.chamadas.emCasa === 1 && j.pedidosVG() === 0, r);\n  }\n\n  t.secao('OS TRÊS JUNTOS');\n  {\n    const j = jogo({ respostas: [lista(COMANDOS)], movimentos: MOVIMENTOS }); carregarNucleo(SRC, j);\n    await deuses(j); await feiticos(j);\n    j.localStorage.setItem('grepoReforco_cfg_v1', JSON.stringify({ ativo: true }));\n    await reforco(j);\n    t.verifica('deuses + feitiços + reforço seguidos → 1 pedido à visão geral', j.pedidosVG() === 1, j.pedidosVG());\n  }\n  t.fim();\n})().catch((e) => { console.error('O TESTE REBENTOU:', e); process.exit(2); });\n",
 "teste-mesma-ilha-nc.js": "/* MESMA ILHA — não dá para medir, logo avisa-se.\n *\n * A velocidade calcula-se com a distância entre ILHAS; na mesma ilha é zero e\n * não há nada para medir. O código assumia que um colonizador não vinha da\n * própria ilha — e vem: uma conquista dentro da ilha foi anunciada como\n * \"tropa terrestre a pé\" (visto em jogo, 14/09, 45.1, de 494:506 para\n * 494:506). O `classificar` e o `pareceNC` REAIS.\n *\n *   node ferramentas/teste-mesma-ilha-nc.js maestro.user.js\n */\nconst S = require('./simulador');\nconst { vm, funcao } = S;\nconst SRC = S.ficheiroDoMaestro();\nconst t = S.verificador('MESMA ILHA');\n\nfunction alertas() {\n  const ctx = {\n    uw: { GameData: { units: { colonize_ship: { speed: 9, is_naval: true }, bireme: { speed: 45, is_naval: true } },\n      powers: { unit_movement_boost: { meta_defaults: { percent: 30 } } } } },\n    seErroDeCodigo: () => {}, console, Math, Number, Object,\n  };\n  vm.createContext(ctx);\n  const a = SRC.indexOf('  const FOLGA_MEDICAO_NC =');\n  const b = SRC.indexOf('  try {\\n    uw.__maestroNC = {', a);\n  return vm.runInContext(SRC.slice(a, b)\n    + funcao(SRC, '  function classificar(vel, mesmaIlha) {') + '\\nclassificar', ctx);\n}\n\n/* `demoras` = o que o jogo já disse sobre este par de cidades (ou null, se\n * ainda não se sabe). */\nfunction esquiva(mesmaIlha, demoras, durou) {\n  const pedidos = [];\n  const ctx = {\n    mUw: {}, seErroDeCodigo: () => {}, console, Math, Number, Promise,\n    coordsOrigem: () => ({ x: 494, y: 506 }),\n    primeiraVezQueVi: () => ({ quando: 9000 - (durou || 0), novo: false }),\n    vistoNoArranque: () => false, agoraJogo: () => 2000,\n    tempoPreparacao: () => 0, rotina: () => {},\n    pareceColonizadorNC: () => ({ nc: false }),\n    ilhaDe: () => null,\n    window: { __maestroDemoras: {\n      guardadas: () => demoras || null,\n      ler: async () => { pedidos.push(1); return demoras || null; },\n      explicam: (d, seg) => (d && d.explicam ? d.explicam(seg) : []),\n    } },\n  };\n  vm.createContext(ctx);\n  const f = vm.runInContext(funcao(SRC, '  function mesmaIlhaTrazNC(a, alvo) {')\n    + funcao(SRC, '  function pareceNC(a, alvo, c) {') + '\\npareceNC', ctx);\n  const alvo = mesmaIlha ? { ix: 494, iy: 506 } : { ix: 500, iy: 500 };\n  return { r: f({ arrival_at: 9000, home_town_id: 1, target_town_id: 2 }, alvo, { K: 100 }), pedidos };\n}\n\n(async () => {\n  const cl = alertas();\n  {\n    const r = cl(18, true);\n    t.verifica('mesma ilha: diz que não dá para medir e marca como possível colonizador',\n      r.nc === true && r.grave === true && !r.certo && /mesma ilha/i.test(r.cat), r);\n  }\n  {\n    const r = cl(45, false);\n    t.verifica('entre ilhas continua a distinguir: birreme não é colonizador', !r.nc, r);\n  }\n  {\n    const r = cl(9, false);\n    t.verifica('entre ilhas, velocidade de colonizador: acusa', r.nc, r);\n  }\n  {\n    const x = esquiva(true, null, 800);\n    t.verifica('mesma ilha sem demoras sabidas: assume o pior e vai pedi-las',\n      x.r === true && x.pedidos.length === 1, x);\n  }\n  {\n    /* Já se sabe: 800 s só é explicado pelo colonizador. */\n    const dem = { explicam: () => [{ id: 'colonize_ship', bonus: 'sem bónus' }] };\n    t.verifica('mesma ilha, demora de colonizador: acusa', esquiva(true, dem, 800).r === true);\n  }\n  {\n    const dem = { explicam: () => [{ id: 'sword', bonus: 'sem bónus' }] };\n    t.verifica('mesma ilha, demora de tropa a pé: já NÃO acusa', esquiva(true, dem, 620).r === false);\n  }\n  {\n    const dem = { explicam: () => [] };\n    t.verifica('nada explica o tempo: assume o pior', esquiva(true, dem, 100).r === true);\n  }\n  t.fim();\n})().catch((e) => { console.error('O TESTE REBENTOU:', e); process.exit(2); });\n",
 "teste-nucleo.js": "/* NÚCLEO — o leitor da visão geral (`__maestroVisaoGeral`): o código REAL,\n * tirado do maestro.user.js, contra um jogo simulado. Cópia, `fresca`,\n * esquecer, pedidos ao mesmo tempo, 429, erros, sem Administrador.\n *\n *   node ferramentas/teste-nucleo.js maestro.user.js\n */\nconst fs = require('fs');\nconst vm = require('vm');\n\nconst ficheiro = process.argv[2] || 'maestro.user.js';\nconst src = fs.readFileSync(ficheiro, 'utf8');\n\nconst ini = src.indexOf('  async function lerRespostaComum(resposta) {');\nconst fim = src.indexOf('  /* ============ AVISO DE VERIFICAÇÃO DE BOT');\nif (ini < 0 || fim < 0 || fim < ini) throw new Error('não encontrei o bloco do núcleo');\nconst bloco = src.slice(ini, fim);\n\nlet falhas = 0;\nlet n = 0;\nfunction verifica(nome, cond, extra) {\n  n++;\n  if (cond) console.log('  ok  ', nome);\n  else { falhas++; console.log('  FALHA', nome, extra !== undefined ? JSON.stringify(extra) : ''); }\n}\n\n/* Um jogo novo para cada cenário. `respostas` é uma fila: cada pedido tira a\n * primeira. Cada resposta: { status, corpo (objecto ou texto), atraso (ms) }. */\nfunction montar(opcoes) {\n  const op = opcoes || {};\n  const pedidos = [];\n  const caixa = [];\n  const captchas = [];\n  const travoes = [];\n  const respostas = (op.respostas || []).slice();\n  let agora = 1_000_000;\n  const premium = op.premium === undefined ? { k: { attributes: { curator: 9e9 } } } : op.premium;\n\n  const uw = {\n    location: { origin: 'https://pt125.grepolis.com' },\n    Game: { csrfToken: 'TOK', townId: 999 },\n    ITowns: { towns: op.semCidades ? {} : { 111: {}, 222: {} } },\n    MM: { getModels: () => ({ PremiumFeatures: premium }) },\n    fetch: async (url, o) => {\n      pedidos.push({ url, o });\n      const r = respostas.shift() || { status: 200, corpo: { json: { commands: [] } } };\n      if (r.lanca) throw new Error(r.lanca);\n      if (r.atraso) await new Promise((res) => setTimeout(res, r.atraso));\n      const texto = typeof r.corpo === 'string' ? r.corpo : JSON.stringify(r.corpo);\n      return { status: r.status || 200, text: async () => texto };\n    },\n  };\n\n  const ctx = {\n    uw,\n    Date: Object.assign(function () {}, { now: () => agora }),\n    JSON, Object, Array, Number, String, Math, Promise, Error, encodeURIComponent,\n    setTimeout,\n    temAdministrador: () => !!(op.temAdm !== false),\n    servidorTravado: () => !!op.travado,\n    avisarCaptcha: async (onde) => { captchas.push(onde); },\n    guardarNaCaixa: (m, t) => { caixa.push(t); },\n    seErroDeCodigo: () => {},\n    log: () => {},\n  };\n  /* `Date` falso só com o `now`; o resto (new Date) não é usado no leitor,\n   * excepto no estado — aí vai o verdadeiro. */\n  ctx.Date = new Proxy(Date, { get: (t, p) => (p === 'now' ? () => agora : t[p]) });\n  vm.createContext(ctx);\n  /* O leitor comum chama `uw.__maestroTravar` no 429. */\n  uw.__maestroTravar = (min) => travoes.push(min);\n  vm.runInContext(bloco, ctx);\n  return {\n    uw, pedidos, caixa, captchas, travoes,\n    avancar: (ms) => { agora += ms; },\n    vg: (o) => uw.__maestroVisaoGeral(o),\n    esquecer: () => uw.__maestroVisaoGeralEsquecer(),\n    estado: () => uw.__maestroVisaoGeralEstado(),\n  };\n}\n\nconst LISTA = [\n  { id: 1, type: 'attack', origin_town_id: 5, destination_town_id: 111, arrival_at: 2000 },\n  { id: 2, type: 'support', origin_town_id: 111, destination_town_id: 7, arrival_at: 3000 },\n];\nconst ok = (lista) => ({ status: 200, corpo: { json: { commands: lista } } });\nconst okData = (lista) => ({ status: 200, corpo: { json: { data: { commands: lista } } } });\n\n(async () => {\n  console.log('\\nLEITURA');\n  {\n    const j = montar({ respostas: [ok(LISTA)] });\n    const r = await j.vg();\n    verifica('json.commands → ok com a lista', r.ok && r.comandos.length === 2 && r.razao === '', r);\n    const u = j.pedidos[0].url;\n    verifica('pedido: GET à command_overview, primeira cidade, token, json',\n      /\\/game\\/town_overviews\\?town_id=111&action=command_overview&h=TOK&json=/.test(u)\n      && !(j.pedidos[0].o || {}).method, u);\n    verifica('pedido com x-requested-with e credenciais',\n      j.pedidos[0].o.headers['x-requested-with'] === 'XMLHttpRequest'\n      && j.pedidos[0].o.credentials === 'include');\n  }\n  {\n    const j = montar({ respostas: [okData(LISTA)] });\n    const r = await j.vg();\n    verifica('json.data.commands → ok com a lista', r.ok && r.comandos.length === 2, r);\n  }\n  {\n    const j = montar({ respostas: [ok([])] });\n    const r = await j.vg();\n    verifica('lista vazia de verdade → ok com []', r.ok && Array.isArray(r.comandos) && r.comandos.length === 0, r);\n  }\n  {\n    const j = montar({ respostas: [{ status: 200, corpo: { json: { outra: 1 } } }] });\n    const r = await j.vg();\n    verifica('resposta sem lista → ok:false, comandos null, diz as chaves',\n      !r.ok && r.comandos === null && /não traz a lista.*outra/.test(r.razao), r);\n    verifica('... e fica na caixa da rotina', j.caixa.length === 1, j.caixa);\n  }\n  {\n    const j = montar({ semCidades: true, respostas: [ok(LISTA)] });\n    const r = await j.vg();\n    verifica('sem ITowns → usa Game.townId', r.ok && /town_id=999&/.test(j.pedidos[0].url), j.pedidos[0]);\n  }\n\n  console.log('\\nFALHAS');\n  {\n    const j = montar({ respostas: [{ status: 200, corpo: { json: { error: 'Algo correu mal' } } }] });\n    const r = await j.vg();\n    verifica('erro do jogo → ok:false com a razão', !r.ok && r.comandos === null && r.razao === 'Algo correu mal', r);\n  }\n  {\n    const j = montar({ respostas: [{ status: 429, corpo: '' }] });\n    const r = await j.vg();\n    verifica('429 → ok:false e o núcleo trava', !r.ok && /recusar/.test(r.razao) && j.travoes.length === 1, r);\n  }\n  {\n    const j = montar({ respostas: [{ status: 200, corpo: '<html>erro</html>' }] });\n    const r = await j.vg();\n    verifica('página de erro → ok:false', !r.ok && /página de erro/.test(r.razao), r);\n  }\n  {\n    const j = montar({ respostas: [{ status: 200, corpo: '' }] });\n    const r = await j.vg();\n    verifica('resposta vazia → ok:false', !r.ok && /não respondeu/.test(r.razao), r);\n  }\n  {\n    const j = montar({ respostas: [{ lanca: 'NetworkError' }] });\n    const r = await j.vg();\n    verifica('fetch rebenta → ok:false', !r.ok && /pedido falhou: NetworkError/.test(r.razao), r);\n  }\n  {\n    const j = montar({ respostas: [{ status: 200, corpo: { json: { error: 'backend_requested_verification' } } }] });\n    const r = await j.vg();\n    verifica('verificação de bot → ok:false e avisa', !r.ok && /verificação/.test(r.razao)\n      && j.captchas.length === 1, { r, captchas: j.captchas });\n  }\n  {\n    const j = montar({ travado: true, respostas: [ok(LISTA)] });\n    const r = await j.vg();\n    verifica('servidor travado → ok:false SEM pedido', !r.ok && j.pedidos.length === 0 && /limitar/.test(r.razao), r);\n  }\n\n  console.log('\\nADMINISTRADOR');\n  {\n    const j = montar({ temAdm: false, respostas: [ok(LISTA)] });\n    const r = await j.vg();\n    verifica('sem Administrador → ok:false SEM pedido', !r.ok && r.razao === 'sem Administrador'\n      && j.pedidos.length === 0, r);\n    verifica('... calado (nada na caixa)', j.caixa.length === 0, j.caixa);\n  }\n  {\n    const j = montar({ premium: {}, temAdm: false, respostas: [ok(LISTA)] });\n    const r = await j.vg();\n    verifica('modelo das assinaturas por carregar → pede e decide o servidor',\n      r.ok && j.pedidos.length === 1, r);\n  }\n  {\n    const j = montar({ respostas: [\n      { status: 200, corpo: { json: { error: 'Necessita do administrador para aceder às visões gerais' } } },\n      ok(LISTA)] });\n    const r1 = await j.vg();\n    const r2 = await j.vg({ fresca: true });\n    verifica('servidor diz \"administrador\" → ok:false', !r1.ok && r1.razao === 'sem Administrador', r1);\n    verifica('... e não volta a pedir durante 30 min (nem com fresca)', !r2.ok && j.pedidos.length === 1, r2);\n    j.avancar(31 * 60 * 1000);\n    const r3 = await j.vg();\n    verifica('... passados 30 min volta a pedir', r3.ok && j.pedidos.length === 2, r3);\n  }\n\n  console.log('\\nCÓPIA PARTILHADA');\n  {\n    const j = montar({ respostas: [ok(LISTA), ok(LISTA.slice(0, 1))] });\n    const r1 = await j.vg();\n    j.avancar(10 * 1000);\n    const r2 = await j.vg();\n    verifica('dentro de 20 s → da cópia, sem pedido', r2.ok && r2.daCopia && j.pedidos.length === 1, r2);\n    verifica('... com a hora da leitura original', r2.quando === r1.quando);\n    j.avancar(11 * 1000);\n    const r3 = await j.vg();\n    verifica('passados 20 s → pedido novo', !r3.daCopia && j.pedidos.length === 2 && r3.comandos.length === 1, r3);\n  }\n  {\n    const j = montar({ respostas: [ok(LISTA), ok(LISTA.slice(0, 1))] });\n    await j.vg();\n    const r = await j.vg({ fresca: true });\n    verifica('fresca → salta a cópia', j.pedidos.length === 2 && r.comandos.length === 1 && !r.daCopia, r);\n    const r2 = await j.vg();\n    verifica('... e a leitura fresca passa a ser a cópia', r2.daCopia && r2.comandos.length === 1, r2);\n  }\n  {\n    const j = montar({ respostas: [ok(LISTA), ok(LISTA.slice(0, 1))] });\n    await j.vg();\n    j.esquecer();\n    const r = await j.vg();\n    verifica('esquecer → o pedido seguinte vai ao servidor', j.pedidos.length === 2 && !r.daCopia, r);\n  }\n  {\n    const j = montar({ respostas: [ok(LISTA)] });\n    const a = await j.vg();\n    a.comandos[0].type = 'MEXIDO';\n    a.comandos.push({ id: 99 });\n    const b = await j.vg();\n    verifica('cada módulo recebe a sua cópia (mexer numa não mexe na outra)',\n      b.comandos.length === 2 && b.comandos[0].type === 'attack', b.comandos);\n  }\n  {\n    const j = montar({ respostas: [ok(LISTA)] });\n    const r = await j.vg();\n    j.avancar(5000);\n    const e = j.estado();\n    verifica('estado na consola', e.pedidos === 1 && /2 comando\\(s\\), de há 5 s/.test(e.copia)\n      && e.administrador === 'sim', e);\n    void r;\n  }\n  {\n    const j = montar({ respostas: [{ status: 200, corpo: { json: { error: 'x' } } }, ok(LISTA)] });\n    await j.vg();\n    const r = await j.vg();\n    verifica('uma falha não fica como cópia (o seguinte pede de novo)', r.ok && j.pedidos.length === 2, r);\n  }\n\n  console.log('\\nPEDIDOS AO MESMO TEMPO');\n  {\n    const j = montar({ respostas: [{ ...ok(LISTA), atraso: 30 }] });\n    const [a, b, c] = await Promise.all([j.vg(), j.vg(), j.vg()]);\n    verifica('três pedidos ao mesmo tempo → um só pedido ao servidor',\n      j.pedidos.length === 1 && a.ok && b.ok && c.ok, j.pedidos.length);\n    verifica('... o primeiro fez o pedido, os outros partilharam',\n      !a.daCopia && b.daCopia && c.daCopia && j.estado().partilhados === 2, j.estado());\n    verifica('... e cada um com a sua cópia', a.comandos !== b.comandos && b.comandos !== c.comandos);\n  }\n  {\n    const j = montar({ respostas: [{ ...ok(LISTA), atraso: 30 }, ok(LISTA)] });\n    const pa = j.vg();\n    const pb = j.vg({ fresca: true });\n    await Promise.all([pa, pb]);\n    verifica('fresca não aproveita um pedido já a caminho', j.pedidos.length === 2, j.pedidos.length);\n  }\n  {\n    /* Envio a meio de uma leitura: a lista que vem pode não ter o envio. */\n    const j = montar({ respostas: [{ ...ok(LISTA), atraso: 30 }, ok(LISTA.slice(0, 1))] });\n    const pa = j.vg();\n    await new Promise((r) => setTimeout(r, 5));\n    j.esquecer();                                    // um módulo mandou tropa\n    const pb = j.vg();                               // pede depois do envio\n    const [a, b] = await Promise.all([pa, pb]);\n    verifica('esquecer a meio: quem pediu antes recebe a lista antiga', a.ok && a.comandos.length === 2, a);\n    verifica('... quem pediu depois NÃO partilha o pedido antigo', j.pedidos.length === 2\n      && b.comandos.length === 1, { pedidos: j.pedidos.length, b });\n    const c = await j.vg();\n    verifica('... e a cópia que fica é a nova', c.daCopia && c.comandos.length === 1, c);\n  }\n  {\n    const j = montar({ respostas: [{ ...ok(LISTA), atraso: 30 }] });\n    const pa = j.vg();\n    await new Promise((r) => setTimeout(r, 5));\n    j.esquecer();\n    await pa;\n    const e = j.estado();\n    verifica('esquecer a meio: a resposta antiga não fica como cópia', e.copia === 'nenhuma', e);\n  }\n  {\n    const j = montar({ respostas: [{ status: 200, corpo: { json: { error: 'x' } }, atraso: 20 }] });\n    const [a, b] = await Promise.all([j.vg(), j.vg()]);\n    verifica('falha partilhada → os dois recebem ok:false', !a.ok && !b.ok && j.pedidos.length === 1);\n  }\n\n  console.log(`\\n${n - falhas}/${n} verificações passaram.`);\n  process.exit(falhas ? 1 : 0);\n})();\n",
 "teste-painel-relatorios.js": "/* PAINEL DOS RELATÓRIOS — o botão Guardar.\n *\n * O visto dos transportes nunca esteve no HTML, e o `.checked` de um campo\n * que não existe rebentava o Guardar inteiro: não se guardava nada, nem o\n * resto. O painel REAL, desenhado num DOM de mentira.\n *\n *   node ferramentas/teste-painel-relatorios.js maestro.user.js\n */\nconst S = require('./simulador');\nconst { vm, tira } = S;\nconst SRC = S.ficheiroDoMaestro();\nconst t = S.verificador('PAINEL DOS RELATÓRIOS');\n\n/* Um DOM só com o que o painel usa: ids, checked, value e onclick. */\nfunction dom(html) {\n  const els = {};\n  const re = /id=\\\\?\"([a-z-]+)\\\\?\"([^>]*)/g;\n  let m;\n  while ((m = re.exec(html))) {\n    const resto = m[2] || '';\n    els[m[1]] = { checked: / checked/.test(resto), value: (resto.match(/value=\\\\?\"([^\"\\\\]*)/) || [])[1] || '' };\n  }\n  return { querySelector: (s) => els[s.replace('#', '')] || null, els };\n}\n\nfunction painel(cfgInicial) {\n  const loja = { 'grepoRelatorios_cfg_v1': JSON.stringify(cfgInicial || {}) };\n  const guardado = [];\n  /* O módulo inteiro, com o `armazem` e o `normalizar` que ele espera. */\n  const txt = S.fabrica(SRC, 'makeRelatoriosModule')\n    + \"\\nmakeRelatoriosModule({ intervaloMin: 60 })\";\n  const ctx = {\n    window: { __maestroArmazem: {\n      getItem: (k) => (k in loja ? loja[k] : null),\n      setItem: (k, v) => { loja[k] = v; try { guardado.push(JSON.parse(v)); } catch (e) {} },\n    } },\n    localStorage: { getItem: () => null, setItem: () => {} },\n    seErroDeCodigo: () => {}, console,\n  };\n  vm.createContext(ctx);\n  return { mod: vm.runInContext(txt, ctx), guardado, loja };\n}\n\n(async () => {\n  let p;\n  try { p = painel({ ativo: true, apoios: true, transportes: false, ler: true, lerMax: 7 }); }\n  catch (e) { console.error('não consegui montar o painel:', e.message); process.exit(2); }\n\n  /* Desenhar o painel: recolhe-se o HTML que ele produz. */\n  let html = '';\n  const container = {\n    set innerHTML(v) { html = v; Object.assign(this, dom(v)); },\n    get innerHTML() { return html; },\n    querySelector: () => null,\n  };\n  p.mod.painel(container, { log: () => {}, uw: {} });\n\n  t.verifica('o painel tem o visto dos transportes', !!container.querySelector('#rel-transp'),\n    Object.keys(container.els || {}));\n  t.verifica('... e o visto de ler os relatórios', !!container.querySelector('#rel-ler'));\n\n  const g = container.querySelector('#rel-guardar');\n  t.verifica('o botão Guardar existe', !!g);\n  if (g && g.onclick) {\n    let rebentou = '';\n    try { g.onclick(); } catch (e) { rebentou = e.message; }\n    t.verifica('Guardar não rebenta', !rebentou, rebentou);\n    const ultimo = p.guardado[p.guardado.length - 1] || {};\n    t.verifica('... e guarda o que estava no painel', ultimo.ativo === true && ultimo.apoios === true\n      && ultimo.ler === true && ultimo.lerMax === 7, ultimo);\n  }\n\n  /* Um painel a que falte um campo (versão antiga do HTML, ou outro tema). */\n  const c2 = { innerHTML: '', querySelector: (s) => (s === '#rel-guardar' ? c2.__g : null) };\n  c2.__g = {};\n  try {\n    p.mod.painel(c2, { log: () => {}, uw: {} });\n    let rebentou2 = '';\n    if (c2.__g.onclick) { try { c2.__g.onclick(); } catch (e) { rebentou2 = e.message; } }\n    t.verifica('com os campos todos em falta, Guardar continua sem rebentar', !rebentou2, rebentou2);\n  } catch (e) { t.verifica('com os campos todos em falta, Guardar continua sem rebentar', false, e.message); }\n  t.fim();\n})().catch((e) => { console.error('O TESTE REBENTOU:', e); process.exit(2); });\n",
 "teste-reforco-agendados.js": "/* REFORÇO — tropa já comprometida não se manda.\n *\n * A esquiva e o encaixe agendam envios: a tropa está em casa, mas já tem\n * destino e hora. Se o reforço a levar, o plano chega à hora e não encontra\n * nada. Uma cidade com envio agendado fica de fora do reforço.\n *\n *   node ferramentas/teste-reforco-agendados.js maestro.user.js\n */\nconst S = require('./simulador');\nconst { vm, funcao, igual } = S;\nconst SRC = S.ficheiroDoMaestro();\nconst t = S.verificador('REFORÇO — AGENDADOS');\nconst RE = 'function makeReforcoModule(opts)';\n\nfunction montar(esquiva, encaixe, agora) {\n  const loja = {\n    grepoEsquiva_planos_v1: JSON.stringify(esquiva || {}),\n    grepoEncaixe_planos_v1: JSON.stringify(encaixe || {}),\n  };\n  const ctx = {\n    mUw: { Timestamp: { now: () => agora || 1000 } },\n    armazem: { getItem: (k) => (k in loja ? loja[k] : null) },\n    seErroDeCodigo: () => {}, console, Math, Number, Set, Object, JSON, Date,\n  };\n  vm.createContext(ctx);\n  return vm.runInContext(funcao(SRC, '  function cidadesComEnvioAgendado() {', RE)\n    + '\\ncidadesComEnvioAgendado', ctx);\n}\n\n(async () => {\n  {\n    const f = montar({ 'a@1': { townId: 111, S: 1200 } }, {});\n    t.verifica('cidade com plano de esquiva: fica de fora', [...f()].join() === '111', [...f()]);\n  }\n  {\n    const f = montar({}, { 'b@2': { townId: 222, S: 1100 } });\n    t.verifica('cidade com plano de encaixe: também', [...f()].join() === '222', [...f()]);\n  }\n  {\n    const f = montar({ 'a@1': { townId: 111, S: 1200 } }, { 'b@2': { townId: 222, S: 1100 } });\n    t.verifica('os dois módulos somam-se', igual([...f()].sort(), [111, 222]), [...f()]);\n  }\n  {\n    /* Um plano cuja hora passou há mais de uma hora já não prende nada. */\n    const f = montar({ 'velho@1': { townId: 111, S: 1000 - 7200 } }, {}, 1000);\n    t.verifica('plano velho não prende a cidade', [...f()].length === 0, [...f()]);\n  }\n  {\n    const f = montar({}, {});\n    t.verifica('sem planos: nenhuma cidade de fora', [...f()].length === 0);\n  }\n  {\n    const f = montar({ 'x': { S: 1200 } }, {});\n    t.verifica('plano sem cidade: ignora-se em vez de rebentar', [...f()].length === 0);\n  }\n  t.fim();\n})().catch((e) => { console.error('O TESTE REBENTOU:', e); process.exit(2); });\n",
 "teste-reforco-blocos.js": "/* REFORÇO — não dar a tropa por perdida só porque os modelos não a mostram.\n *\n * Os modelos `Units` são incompletos. Uma lista sem o bloco passava por\n * \"morreu no ataque ou foi retirada\": o registo era apagado e a tropa ficava\n * parada no destino para sempre (visto em jogo, 14/09 — quatro cidades de uma\n * vez em 55.9). Agora confirma-se na Ágora da origem. O `blocosEm` REAL.\n *\n *   node ferramentas/teste-reforco-blocos.js maestro.user.js\n */\nconst S = require('./simulador');\nconst { vm, funcao, igual } = S;\nconst SRC = S.ficheiroDoMaestro();\nconst t = S.verificador('REFORÇO — BLOCOS');\nconst RE = 'function makeReforcoModule(opts)';\n\n/* `modelos`: o que a página tem. `agora`: o que a Ágora responde\n * (null = não consegui ler; lista = o que está fora daquela cidade). */\nfunction montar(modelos, agora) {\n  const pedidos = [];\n  const ctx = {\n    mUw: {\n      MM: { getModels: () => ({ Units: modelos || {} }) },\n      GameData: { units: { sword: {}, archer: {}, hoplite: {}, bireme: {} } },\n      __maestroApoioFora: agora === undefined ? undefined : {\n        daCidade: async (id) => { pedidos.push(id); return agora; },\n      },\n    },\n    seErroDeCodigo: () => {}, console,\n  };\n  vm.createContext(ctx);\n  const f = vm.runInContext(funcao(SRC, '  async function blocosEm(origemId, destinoId) {', RE)\n    + funcao(SRC, '  function blocosPelosModelos(origemId, destinoId) {', RE) + '\\nblocosEm', ctx);\n  return { f, pedidos };\n}\n\nconst MODELO = { m1: { attributes: { id: 417043, home_town_id: 55013, current_town_id: 55009, archer: 559, hoplite: 493 } } };\nconst OUTRO = { m2: { attributes: { id: 999, home_town_id: 55027, current_town_id: 55009, archer: 10 } } };\n\n(async () => {\n  {\n    const m = montar(MODELO);\n    const r = await m.f(55013, 55009);\n    t.verifica('o bloco está nos modelos: usa-o, sem perguntar à Ágora',\n      r.length === 1 && r[0].id === 417043 && igual(r[0].unidades, { archer: 559, hoplite: 493 }), r);\n  }\n  {\n    /* O caso de 14/09: há modelos, mas não o desta origem. */\n    const m = montar(OUTRO, [{ alvoId: 55009, unitsId: 417043, unidades: { archer: 559 } }]);\n    const r = await m.f(55013, 55009);\n    t.verifica('modelos sem o bloco, mas a Ágora tem-no: a tropa ESTÁ lá',\n      r.length === 1 && r[0].id === 417043 && m.pedidos[0] === 55013, { r, p: m.pedidos });\n  }\n  {\n    const m = montar(OUTRO, []);\n    const r = await m.f(55013, 55009);\n    t.verifica('a Ágora responde e não tem nada: aí sim, já não está', igual(r, []), r);\n  }\n  {\n    const m = montar(OUTRO, [{ alvoId: 55018, unitsId: 5, unidades: { sword: 3 } }]);\n    const r = await m.f(55013, 55009);\n    t.verifica('a Ágora só mostra apoio noutra cidade: já não está em 55.9', igual(r, []), r);\n  }\n  {\n    const m = montar(OUTRO, null);\n    const r = await m.f(55013, 55009);\n    t.verifica('a Ágora não conseguiu ler: NÃO SEI (mantém o registo)', r === null, r);\n  }\n  {\n    const m = montar({}, [{ alvoId: 55009, unitsId: 1, unidades: { sword: 1 } }]);\n    const r = await m.f(55013, 55009);\n    t.verifica('modelos por carregar: não sei, sem sequer perguntar', r === null && !m.pedidos.length, { r, p: m.pedidos });\n  }\n  {\n    const m = montar(OUTRO, undefined);\n    const r = await m.f(55013, 55009);\n    t.verifica('sem a Ágora disponível: não sei (não apaga o registo)', r === null, r);\n  }\n  t.fim();\n})().catch((e) => { console.error('O TESTE REBENTOU:', e); process.exit(2); });\n",
 "teste-relatorios.js": "/* LER RELATÓRIOS — o que o jogo diz em cada um.\n *\n * Formato confirmado em jogo (11/09): o HTML vem em `plain.html`, no topo da\n * resposta; cada tropa é `data-unit_id`/`data-unit_count`; o lado está na\n * classe do bloco à volta; as perdas em `report_losts`; o assunto em\n * `<span class=\"subject\">`. O código REAL do módulo contra relatórios com\n * esse formato.\n *\n *   node ferramentas/teste-relatorios.js maestro.user.js\n */\nconst S = require('./simulador');\nconst { vm, tira, igual } = S;\nconst SRC = S.ficheiroDoMaestro();\nconst t = S.verificador('LER RELATÓRIOS');\n\nfunction leitor() {\n  /* Do início do leitor até ao fim do `anotar`: é tudo o que se precisa. */\n  /* Do início do leitor até ao fim do `anotar` — o que não faz pedidos. */\n  const i = SRC.indexOf('  const LIDOS_KEY =');\n  const f = SRC.indexOf('  /* Um relatório: pedir e ler.', i);\n  const txt = SRC.slice(i, f)\n    + '\\n({ lerRelatorio, anotar, ver: () => lerJSON(INIMIGOS_KEY, {}) })';\n  const loja = {};\n  const ctx = { seErroDeCodigo: () => {}, atob: (s) => Buffer.from(s, 'base64').toString('binary'),\n    escape, decodeURIComponent, unescape,\n    armazem: { getItem: (k) => (k in loja ? loja[k] : null), setItem: (k, v) => { loja[k] = v; } } };\n  vm.createContext(ctx);\n  return vm.runInContext(txt, ctx);\n}\n\nconst bloco = (lado, u, n, perdeu) => `<div class=\"report_side_${lado}_unit\">`\n  + `<div class=\"report_unit unit report_side_${lado} unit_${u} unit_icon40x40 ${u}\" `\n  + `data-unit_id=\"${u}\" data-unit_count=\"${n}\"><span class=\"bold\">${n}</span></div>`\n  + (perdeu != null ? `<span class=\"report_losts\">-${perdeu}</span>` : '') + '</div>';\nconst spy = (u, n) => `<div class=\"report_unit unit unit_${u} spy unit_icon40x40 ${u}\" `\n  + `data-unit_id=\"${u}\" data-unit_count=\"${n}\"></div>`;\nconst b64 = (o) => Buffer.from(JSON.stringify(o), 'utf8').toString('base64');\nconst cabecalho = (origem, destino) => `<div id=\"report_sending_town\">`\n  + `<a href=\"#${b64({ id: 421, ix: 502, iy: 512, tp: 'town', name: 'Cidade' })}\" class=\"gp_town_link\">Cidade</a>`\n  + `<a href=\"#${b64({ name: origem, id: 2225917 })}\" class=\"gp_player_link\">${origem}</a></div>`\n  + `<div id=\"report_receiving_town\">`\n  + `<a href=\"#${b64({ name: destino, id: 2379469 })}\" class=\"gp_player_link\">${destino}</a></div>`;\n\n/* Os quatro casos que a espia mostrou. */\nconst ATAQUE = `<span class=\"subject\">126-55-002 (Godfather) está a atacar 45.9</span>`\n  + cabecalho('Godfather', 'Shad0wRA')\n  + bloco('attacker', 'rider', 35, 35)\n  + bloco('defender', 'bireme', 3110, 0) + bloco('defender', 'sword', 4500, 13)\n  + bloco('defender', 'militia', 375, 1);\nconst MEU_ATAQUE = `<span class=\"subject\">55.25 está a atacar 45 - 02 (RJFS23)</span>`\n  + cabecalho('Shad0wRA', 'RJFS23')\n  + bloco('attacker', 'attack_ship', 298, 298) + bloco('defender', 'bireme', 400, 12);\nconst ESPIA_OK = `<span class=\"subject\">55.13 está a espiar 55 - 04 (RJFS23)</span>`\n  + cabecalho('Shad0wRA', 'RJFS23') + spy('sword', 1486) + spy('archer', 1558) + spy('bireme', 90);\nconst ESPIA_MA = `<span class=\"subject\">Espião de 126-55-002 (Godfather) descoberto na cidade 45.9</span>`\n  + cabecalho('Godfather', 'Shad0wRA');\n\n(async () => {\n  const L = leitor();\n  {\n    const d = L.lerRelatorio(ATAQUE);\n    t.verifica('ataque recebido: a tropa do atacante e o que perdeu', igual(d.atacante, { rider: 35 })\n      && igual(d.perdasAtacante, { rider: 35 }), d);\n    t.verifica('... e a defesa, com as perdas', d.defensor.bireme === 3110 && d.defensor.sword === 4500\n      && d.perdasDefensor.sword === 13 && !d.perdasDefensor.bireme, d);\n    t.verifica('... quem ataca e quem é atacado', d.jogadorOrigem === 'Godfather' && d.jogadorDestino === 'Shad0wRA', d);\n  }\n  {\n    const d = L.lerRelatorio(MEU_ATAQUE);\n    t.verifica('ataque meu: o atacante sou eu, o defensor é o outro', d.jogadorOrigem === 'Shad0wRA'\n      && d.jogadorDestino === 'RJFS23' && d.atacante.attack_ship === 298 && d.defensor.bireme === 400, d);\n  }\n  {\n    const d = L.lerRelatorio(ESPIA_OK);\n    t.verifica('espionagem certa: a tropa da cidade espiada', igual(d.espiada, { sword: 1486, archer: 1558, bireme: 90 })\n      && !Object.keys(d.atacante).length, d);\n  }\n  {\n    const d = L.lerRelatorio(ESPIA_MA);\n    t.verifica('espião apanhado: sem tropas, mas com o assunto e os jogadores',\n      !Object.keys(d.espiada).length && /descoberto/.test(d.assunto) && d.jogadorOrigem === 'Godfather', d);\n  }\n  {\n    const L2 = leitor();\n    L2.anotar('Vilão', 'atacou', { sword: 100 }, 1000);\n    L2.anotar('Vilão', 'atacou', { sword: 500, rider: 50 }, 2000);\n    L2.anotar('Vilão', 'atacou', { sword: 10 }, 3000);\n    const j = L2.ver()['Vilão'];\n    t.verifica('guarda a maior força que o jogador já trouxe', igual(j.atacou, { sword: 500, rider: 50 })\n      && j.atacouQuando === 2000, j);\n    t.verifica('... e conta as vezes e a última', j.vezes === 3 && j.ultimo === 3000, j);\n    L2.anotar('Vilão', 'espiado', { hoplite: 900 }, 4000);\n    t.verifica('... o que se lhe viu em casa fica à parte', igual(L2.ver()['Vilão'].espiado, { hoplite: 900 })\n      && igual(L2.ver()['Vilão'].atacou, { sword: 500, rider: 50 }));\n    t.verifica('sem tropas não se anota nada', L2.anotar('Outro', 'atacou', {}, 5000) === false && !L2.ver().Outro);\n  }\n  t.fim();\n})().catch((e) => { console.error('O TESTE REBENTOU:', e); process.exit(2); });\n",
 "teste-sentinelas.js": "/* SENTINELAS — não mandar outra só porque não se viu a que lá está.\n *\n * A leitura da Ágora cobre só ALGUMAS das minhas cidades de cada vez. Uma\n * sentinela enviada de uma cidade por ler não aparece — e concluir daí que a\n * aliada está a descoberto punha lá outra, e outra: apareceram cidades com 15\n * sentinelas (visto em jogo, 13/09). O `tenhoTropaEm` REAL.\n *\n *   node ferramentas/teste-sentinelas.js maestro.user.js\n */\nconst S = require('./simulador');\nconst { vm, funcao } = S;\nconst SRC = S.ficheiroDoMaestro();\nconst t = S.verificador('SENTINELAS');\nconst SE = 'function makeSentinelasModule(opts)';\n\n/* As minhas cidades são 111 e 222. `porAlvo` é o que a Ágora deu; `lidas` são\n * as minhas cidades que essa leitura cobre; `modelos` é o que a página tem. */\nfunction montar(porAlvo, lidas, modelos) {\n  const ctx = {\n    mUw: {\n      ITowns: { towns: { 111: {}, 222: {} } },\n      MM: { getModels: () => ({ Units: modelos || {} }) },\n      __maestroApoioFora: porAlvo === undefined ? undefined\n        : { porAlvo: () => porAlvo, lidas: () => lidas || [] },\n    },\n    seErroDeCodigo: () => {}, console,\n  };\n  vm.createContext(ctx);\n  return vm.runInContext(funcao(SRC, '  function tenhoTropaEm(townId) {', SE)\n    + funcao(SRC, '  function tenhoTropaEmPelosModelos(townId) {', SE) + '\\ntenhoTropaEm', ctx);\n}\n\nconst COM_SENTINELA = { 9001: { unidades: { sword: 3 } } };\nconst MODELO_LA = { u1: { attributes: { id: 1, home_town_id: 111, current_town_id: 9001, sword: 3 } } };\n\n(async () => {\n  {\n    const f = montar(COM_SENTINELA, [111, 222]);\n    t.verifica('a sentinela aparece na leitura: está lá', f(9001) === true);\n  }\n  {\n    const f = montar({}, [111, 222]);\n    t.verifica('leitura completa e sem nada lá: está mesmo a descoberto', f(9001) === false);\n  }\n  {\n    const f = montar({}, [111]);\n    t.verifica('leitura só de uma das minhas cidades: NÃO SEI (não manda)', f(9001) === null);\n  }\n  {\n    const f = montar(null, []);\n    t.verifica('sem leitura nenhuma: não sei', f(9001) === null);\n  }\n  {\n    const f = montar(undefined);\n    t.verifica('sem a Ágora sequer: não sei', f(9001) === null);\n  }\n  {\n    const f = montar({}, [111], MODELO_LA);\n    t.verifica('os modelos mostram a tropa lá: chega para dizer que está', f(9001) === true);\n  }\n  {\n    const f = montar(COM_SENTINELA, [111, 222]);\n    t.verifica('outra cidade aliada, essa vazia: está a descoberto', f(9002) === false);\n  }\n  t.fim();\n})().catch((e) => { console.error('O TESTE REBENTOU:', e); process.exit(2); });\n",
 "teste-silencios.js": "/* ACÇÕES QUE RESPONDEM CALADAS, E ESCRITAS QUE FALHAM EM SILÊNCIO.\n *\n * \"Não veio erro\" contava por feito, e um `catch` vazio à volta de uma\n * escrita perdia definições sem dizer nada. Nenhuma das duas coisas mudava de\n * comportamento — mudavam de visibilidade, que é o primeiro passo para as\n * corrigir com dados.\n *\n *   node ferramentas/teste-silencios.js maestro.user.js\n */\nconst S = require('./simulador');\nconst { vm, tira } = S;\nconst SRC = S.ficheiroDoMaestro();\nconst t = S.verificador('SILÊNCIOS');\n\nfunction nucleo() {\n  const caixa = [];\n  const ctx = {\n    uw: {}, guardarNaCaixa: (m, txt) => caixa.push(txt), console, Object, Number, String,\n  };\n  vm.createContext(ctx);\n  const a = SRC.indexOf('  const respostasMudas = {};');\n  const b = SRC.indexOf('\\n  function seErroDeCodigo(e, onde) {', a);\n  vm.runInContext(SRC.slice(a, b), ctx);\n  return { ctx, caixa };\n}\n\n(async () => {\n  {\n    const n = nucleo();\n    n.ctx.anotarRespostaMuda('https://pt126.grepolis.com/game/building_barracks?town_id=1&action=build&h=X');\n    t.verifica('regista a acção que respondeu calada',\n      n.ctx.uw.__maestroRespostasMudas()['building_barracks:build'] === 1,\n      n.ctx.uw.__maestroRespostasMudas());\n    t.verifica('... e deixa uma linha na caixa, uma só',\n      n.caixa.length === 1 && /sem confirmação/.test(n.caixa[0]), n.caixa);\n    n.ctx.anotarRespostaMuda('https://pt126.grepolis.com/game/building_barracks?town_id=1&action=build&h=X');\n    t.verifica('a segunda vez conta mas não repete a linha',\n      n.ctx.uw.__maestroRespostasMudas()['building_barracks:build'] === 2 && n.caixa.length === 1);\n  }\n  {\n    const n = nucleo();\n    n.ctx.anotarRespostaMuda('https://x/game/town_info?action=send_units&h=Y');\n    n.ctx.anotarRespostaMuda('https://x/game/frontend_bridge?action=execute&h=Y');\n    t.verifica('acções diferentes ficam separadas',\n      Object.keys(n.ctx.uw.__maestroRespostasMudas()).length === 2,\n      n.ctx.uw.__maestroRespostasMudas());\n  }\n  {\n    /* Uma escrita que falha por falta de espaço passa a ser reportada. */\n    const vistos = [];\n    const ctx = { log: (m, txt) => vistos.push(txt), errosJaVistos: new Set(), console };\n    vm.createContext(ctx);\n    const i = SRC.indexOf('  function seErroDeCodigo(e, onde) {');\n    const f = SRC.indexOf('\\n  }\\n', i) + 4;\n    vm.runInContext(SRC.slice(i, f) + '\\nseErroDeCodigo', ctx);\n    ctx.seErroDeCodigo(new Error('QuotaExceededError: persistent storage'), 'Apoio');\n    t.verifica('falha a guardar: reportada', vistos.some((x) => /Apoio/.test(x)), vistos);\n    ctx.seErroDeCodigo(new Error('coisa qualquer prevista'), 'Apoio');\n    t.verifica('falha prevista: continua em silêncio', vistos.length === 1, vistos);\n  }\n  t.fim();\n})().catch((e) => { console.error('O TESTE REBENTOU:', e); process.exit(2); });\n",
 "teste-vigia-mudo.js": "/* VIGIA — um módulo que corre e não faz nada.\n *\n * A frota já dizia quando cada módulo correu; correr não é fazer. A recolha a\n * render zero e o fechar ilha a ver vagas a mais passaram horas a correr sem\n * produzir nada e ninguém deu por isso (12/09). O núcleo passa a marcar a hora\n * de cada linha de ECRÃ (as de rotina não contam) e o vigia avisa.\n *\n *   node ferramentas/teste-vigia-mudo.js maestro.user.js\n */\nconst S = require('./simulador');\nconst { vm, tira, igual } = S;\nconst SRC = S.ficheiroDoMaestro();\nconst t = S.verificador('VIGIA — MÓDULO MUDO');\n\n/* A marcação no núcleo. */\nfunction nucleo() {\n  const loja = {};\n  const ctx = {\n    localStorage: { getItem: (k) => loja[k] || null, setItem: (k, v) => { loja[k] = v; } },\n    setInterval: () => 0, uw: {}, seErroDeCodigo: () => {},\n  };\n  vm.createContext(ctx);\n  vm.runInContext(tira(SRC, '  /* A última vez que cada módulo fez alguma coisa', '  const MODULES = [];'), ctx);\n  return ctx;\n}\n\n/* O troço do vigia que decide quem está mudo. */\nfunction vigia(modulos, agora) {\n  const ctx = { seErroDeCodigo: () => {}, agora, x: { modulos } };\n  vm.createContext(ctx);\n  const txt = tira(SRC, '  const VIGIADOS = {', '  };\\n')\n    + 'const parados = [];\\n'\n    + tira(SRC, '      try {\\n        for (const id of Object.keys(VIGIADOS)) {', '      } catch (e) { seErroDeCodigo(e, \\'Frota\\'); }\\n')\n    + '\\nparados';\n  return vm.runInContext(txt, ctx);\n}\n\nconst h = (n) => Math.floor(Date.now() / 1000) - n * 3600;\nconst agora = Math.floor(Date.now() / 1000);\n\n(async () => {\n  {\n    const n = nucleo();\n    n.marcarFeito('aldeias');\n    const antes = n.uw.__maestroUltimoFeito().aldeias;\n    t.verifica('marcar: guarda a hora do módulo', antes > 0 && Math.abs(Date.now() - antes) < 2000, antes);\n    n.marcarFeito('apoio');\n    t.verifica('... por módulo, sem misturar', igual(Object.keys(n.uw.__maestroUltimoFeito()).sort(), ['aldeias', 'apoio']));\n  }\n  {\n    t.verifica('aldeias a correr e a fazer: nada a dizer',\n      igual(vigia({ aldeias: { a: 1, u: agora - 300, f: agora - 600 } }, agora), []));\n    t.verifica('aldeias a correr há 3 h sem fazer nada: avisa',\n      igual(vigia({ aldeias: { a: 1, u: agora - 300, f: h(4) } }, agora), ['aldeias']));\n    t.verifica('aldeias desligadas: não avisa',\n      igual(vigia({ aldeias: { a: 0, u: agora - 300, f: h(9) } }, agora), []));\n    t.verifica('módulo que nem está a correr: não avisa (é outro problema)',\n      igual(vigia({ aldeias: { a: 1, u: h(5), f: h(9) } }, agora), []));\n    t.verifica('nunca fez nada desde o arranque: não avisa (f a zero)',\n      igual(vigia({ aldeias: { a: 1, u: agora - 300, f: 0 } }, agora), []));\n    t.verifica('recrutamento calado 13 h: ainda não (pode estar à espera de recursos)',\n      igual(vigia({ recrutamento: { a: 1, u: agora - 300, f: h(13) } }, agora), []));\n    t.verifica('recrutamento calado 25 h: avisa',\n      igual(vigia({ recrutamento: { a: 1, u: agora - 300, f: h(25) } }, agora), ['recrutamento']));\n    /* O tique só trabalha quando há moedas: calado não é avaria. */\n    t.verifica('tique calado há dias: NÃO avisa',\n      igual(vigia({ tique: { a: 1, u: agora - 60, f: h(48) } }, agora), []));\n    t.verifica('módulos que passam dias sem ter o que fazer não são vigiados',\n      igual(vigia({ expansao: { a: 1, u: agora - 300, f: h(48) },\n        fecharilha: { a: 1, u: agora - 300, f: h(48) } }, agora), []));\n    t.verifica('dois mudos ao mesmo tempo: ambos na lista',\n      igual(vigia({ aldeias: { a: 1, u: agora - 60, f: h(5) },\n        construcao: { a: 1, u: agora - 60, f: h(30) } }, agora).sort(), ['aldeias', 'construcao']));\n  }\n  t.fim();\n})().catch((e) => { console.error('O TESTE REBENTOU:', e); process.exit(2); });\n"
};

const destino = path.join(process.cwd(), 'ferramentas');
fs.mkdirSync(destino, { recursive: true });
let n = 0;
for (const nome of Object.keys(FICHEIROS)) {
  fs.writeFileSync(path.join(destino, nome), FICHEIROS[nome], 'utf8');
  n++;
}
console.log(`Escritos ${n} ficheiro(s) em ${destino}`);
console.log('Agora: node ferramentas/testar-tudo.js maestro.user.js');
